window.QBANK = window.QBANK || {};
window.QBANK["smp-bahasa-indonesia"] = {
  level: "SMP", subject: "Bahasa Indonesia", duration: 900,
  questions: [
    { q: "Antonim kata \"rajin\" adalah ....", options: ["Pintar", "Malas", "Cepat", "Kuat"], answer: 1, solution: "Langkah 1: antonim artinya lawan kata. Langkah 2: kata \"rajin\" berarti tekun dalam bekerja atau belajar. Langkah 3: lawan dari tekun bekerja adalah \"malas\"." },
    { q: "Sinonim kata \"bahagia\" adalah ....", options: ["Sedih", "Senang", "Marah", "Takut"], answer: 1, solution: "Langkah 1: sinonim artinya persamaan kata. Langkah 2: kata \"bahagia\" berarti merasa senang atau gembira. Langkah 3: kata yang maknanya sama adalah \"senang\"." },
    { q: "Kalimat efektif yang benar adalah ....", options: ["Para siswa-siswa sedang belajar di kelas.", "Para siswa sedang belajar di kelas.", "Siswa-siswa para sedang belajar di kelas.", "Belajar di kelas para siswa sedang."], answer: 1, solution: "Langkah 1: kalimat efektif tidak boros kata dan susunannya logis. Langkah 2: kata \"para\" sudah menunjukkan jamak, sehingga \"siswa-siswa\" sesudahnya menjadi mubazir. Langkah 3: kalimat yang tepat adalah \"Para siswa sedang belajar di kelas.\"" },
    { q: "Kata berimbuhan yang benar dari kata dasar \"sapu\" dengan awalan me- adalah ....", options: ["Mensapu", "Menyapu", "Mengesapu", "Sapume"], answer: 1, solution: "Langkah 1: perhatikan huruf awal kata dasar, yaitu \"s\". Langkah 2: kaidahnya, awalan me- bertemu huruf \"s\" menjadi meny- (huruf s luluh). Langkah 3: jadi \"me- + sapu\" = \"menyapu\"." },
    { q: "\"Pantai itu indah. Pasirnya putih bersih dan ombaknya berkejaran.\" Kutipan teks tersebut termasuk jenis teks ....", options: ["Narasi", "Deskripsi", "Eksposisi", "Argumentasi"], answer: 1, solution: "Langkah 1: perhatikan isi kutipan, yaitu melukiskan keadaan pantai secara rinci. Langkah 2: teks yang menggambarkan objek seolah-olah pembaca melihatnya sendiri disebut teks deskripsi. Langkah 3: teks narasi menceritakan kejadian, eksposisi menjelaskan, dan argumentasi meyakinkan pembaca." },
    { q: "\"Angin malam berbisik di telingaku.\" Majas yang digunakan dalam kalimat tersebut adalah ....", options: ["Metafora", "Personifikasi", "Hiperbola", "Simile"], answer: 1, solution: "Langkah 1: perhatikan kata \"berbisik\" yang dilakukan oleh angin. Langkah 2: berbisik adalah perbuatan manusia, sedangkan angin adalah benda mati. Langkah 3: majas yang menganggap benda mati seolah-olah manusia disebut personifikasi." },
    { q: "Kata baku dari \"apotik\" adalah ....", options: ["Apotik", "Apotek", "Aphotek", "Apothekk"], answer: 1, solution: "Langkah 1: kata baku adalah kata yang sesuai dengan kaidah bahasa Indonesia dan tercantum di KBBI. Langkah 2: bentuk yang tercantum di KBBI adalah \"apotek\". Langkah 3: jadi penulisan yang baku adalah \"apotek\"." },
    { q: "\"Menjaga kebersihan lingkungan sekolah adalah tanggung jawab seluruh warga sekolah, bukan hanya petugas kebersihan. Setiap siswa wajib membuang sampah pada tempatnya.\" Ide pokok paragraf tersebut adalah ....", options: ["Petugas kebersihan bertugas membersihkan sekolah.", "Kebersihan lingkungan sekolah adalah tanggung jawab seluruh warga sekolah.", "Setiap siswa wajib menjaga kebersihan kelas.", "Membuang sampah harus pada tempatnya."], answer: 1, solution: "Langkah 1: ide pokok biasanya terletak pada kalimat pertama paragraf. Langkah 2: kalimat pertama menyatakan bahwa kebersihan adalah tanggung jawab seluruh warga sekolah. Langkah 3: pilihan B merangkum gagasan tersebut dengan tepat dan lengkap." },
    { q: "Baris pertama dan kedua dalam sebuah pantun disebut ....", options: ["Isi", "Sampiran", "Penutup", "Amanat"], answer: 1, solution: "Langkah 1: pantun terdiri atas empat baris. Langkah 2: dua baris pertama berfungsi sebagai pengantar yang disebut sampiran. Langkah 3: dua baris terakhir merupakan isi pantun." },
    { q: "Penulisan kalimat langsung yang tepat adalah ....", options: ["Ibu berkata \"Cepat pulang, Nak!\"", "Ibu berkata, \"Cepat pulang, Nak!\"", "Ibu berkata: \"Cepat pulang, Nak!\"", "Ibu berkata \"Cepat pulang, Nak!\"."], answer: 1, solution: "Langkah 1: kalimat langsung didahului tanda koma sebelum tanda petik pembuka. Langkah 2: pilihan B memakai koma dengan benar: Ibu berkata, \"...\". Langkah 3: pilihan A tidak memakai koma, C memakai titik dua, dan D salah menempatkan titik." }
,
    { q: "'Pagi itu Rudi bergegas ke sekolah. Di tengah jalan ia melihat sebuah dompet tergeletak. Tanpa ragu ia mengambilnya dan menyerahkannya kepada guru.' Kutipan tersebut termasuk jenis teks ....", options: ["Deskripsi", "Narasi", "Eksposisi", "Puisi"], answer: 1, solution: "Langkah 1: perhatikan isi kutipan yang menceritakan rangkaian peristiwa. Langkah 2: teks yang mengisahkan kejadian atau peristiwa dengan urutan waktu disebut teks narasi. Langkah 3: teks deskripsi melukiskan objek, eksposisi menjelaskan sesuatu, dan puisi terikat oleh bait dan rima." },
    { q: "Ciri utama teks eksposisi adalah ....", options: ["Bersifat menghibur pembaca", "Bersifat informatif dan menjelaskan sesuatu", "Penuh dengan majas dan rima", "Berupa percakapan antartokoh"], answer: 1, solution: "Langkah 1: ingat tujuan dari setiap jenis teks. Langkah 2: teks eksposisi bertujuan memberi informasi dan penjelasan agar wawasan pembaca bertambah. Langkah 3: teks yang menghibur termasuk teks narasi, sedangkan yang penuh majas dan rima adalah puisi." },
    { q: "Bagian teks deskripsi yang berisi gambaran umum tentang objek yang dideskripsikan disebut ....", options: ["Deskripsi bagian", "Identifikasi", "Simpulan", "Koda"], answer: 1, solution: "Langkah 1: ingat struktur teks deskripsi. Langkah 2: bagian pembuka yang berisi gambaran umum objek disebut identifikasi. Langkah 3: deskripsi bagian memerinci ciri-ciri objek, simpulan berisi penegasan, sedangkan koda adalah penutup pada teks narasi." },
    { q: "'Dia adalah bintang kelas yang selalu bersinar.' Majas yang digunakan dalam kalimat tersebut adalah ....", options: ["Personifikasi", "Metafora", "Hiperbola", "Litotes"], answer: 1, solution: "Langkah 1: perhatikan perbandingan 'dia' dengan 'bintang kelas'. Langkah 2: perbandingan langsung tanpa memakai kata pembanding (seperti, bagai) disebut metafora. Langkah 3: personifikasi menganggap benda mati seperti manusia, hiperbola melebih-lebihkan, dan litotes merendahkan diri." },
    { q: "'Suaranya menggelegar membelah angkasa.' Majas yang digunakan dalam kalimat tersebut adalah ....", options: ["Simile", "Hiperbola", "Metafora", "Ironi"], answer: 1, solution: "Langkah 1: perhatikan penggambaran suara yang dilebih-lebihkan. Langkah 2: suara manusia tidak mungkin benar-benar membelah angkasa. Langkah 3: majas yang melebih-lebihkan kenyataan disebut hiperbola." },
    { q: "'Tawanya sekeras guntur di siang bolong.' Majas yang digunakan dalam kalimat tersebut adalah ....", options: ["Personifikasi", "Hiperbola", "Simile", "Metafora"], answer: 2, solution: "Langkah 1: perhatikan kata pembanding 'sekeras' yang berasal dari awalan 'se-' dan kata 'keras'. Langkah 2: perbandingan yang memakai kata pembanding seperti se-, bagai, atau laksana disebut simile. Langkah 3: metafora tidak memakai kata pembanding, sedangkan hiperbola melebih-lebihkan kenyataan." },
    { q: "Ciri khas syair sebagai salah satu puisi rakyat adalah ....", options: ["Terdiri atas sampiran dan isi", "Seluruh baris merupakan isi dengan sajak a-a-a-a", "Hanya terdiri atas dua baris", "Bersajak ab-ab"], answer: 1, solution: "Langkah 1: ingat perbedaan pantun, syair, dan gurindam. Langkah 2: pantun memiliki sampiran dan isi, sedangkan gurindam hanya dua baris. Langkah 3: syair tiap baitnya terdiri atas empat baris yang semuanya merupakan isi dengan pola sajak a-a-a-a." },
    { q: "Gurindam terdiri atas ....", options: ["Empat baris", "Dua baris yang merupakan satu kesatuan sebab-akibat", "Delapan baris", "Jumlah baris yang bebas"], answer: 1, solution: "Langkah 1: ingat bentuk-bentuk puisi rakyat. Langkah 2: gurindam tiap baitnya terdiri atas dua baris. Langkah 3: baris pertama berisi syarat atau persoalan dan baris kedua berisi jawabannya, sehingga keduanya merupakan satu kesatuan." },
    { q: "Kalimat berikut yang efektif adalah ....", options: ["Agar supaya cepat sampai, kami berlari.", "Supaya cepat sampai, kami berlari.", "Demi untuk cepat sampai, kami berlari.", "Untuk agar cepat sampai, kami berlari."], answer: 1, solution: "Langkah 1: kalimat efektif tidak boros kata. Langkah 2: pasangan kata 'agar supaya', 'demi untuk', dan 'untuk agar' mubazir karena kedua katanya bermakna sama. Langkah 3: kalimat yang hemat kata dan tepat adalah 'Supaya cepat sampai, kami berlari.'" },
    { q: "Kata baku dari 'sekedar' adalah ....", options: ["Sekedar", "Sekadar", "Sekedaar", "Skedar"], answer: 1, solution: "Langkah 1: kata baku adalah kata yang sesuai dengan kaidah bahasa Indonesia dan tercantum di KBBI. Langkah 2: bentuk yang tercantum di KBBI adalah 'sekadar' dengan huruf a. Langkah 3: jadi penulisan yang baku adalah 'sekadar'." },
    { q: "Kata berimbuhan yang benar dari kata dasar 'pukul' dengan awalan me- adalah ....", options: ["Mempukul", "Memukul", "Mengepukul", "Nyepukul"], answer: 1, solution: "Langkah 1: perhatikan huruf awal kata dasar, yaitu 'p'. Langkah 2: kaidahnya, awalan me- bertemu huruf 'p' menjadi mem- (huruf p luluh). Langkah 3: jadi 'me- + pukul' = 'memukul'." },
    { q: "Ciri surat dinas adalah ....", options: ["Menggunakan bahasa santai", "Memakai kop surat dan bahasa resmi", "Tidak mencantumkan tanggal surat", "Ditulis dengan bahasa gaul"], answer: 1, solution: "Langkah 1: surat dinas adalah surat resmi dari instansi atau organisasi. Langkah 2: surat resmi memakai kop surat sebagai identitas pengirim dan menggunakan bahasa yang resmi dan baku. Langkah 3: bahasa santai atau gaul hanya dipakai pada surat pribadi." },
    { q: "Bagian surat yang berisi maksud dan tujuan penulisan surat disebut ....", options: ["Salam pembuka", "Isi surat", "Penutup", "Kepala surat"], answer: 1, solution: "Langkah 1: ingat bagian-bagian surat. Langkah 2: kepala surat berisi identitas pengirim dan salam pembuka berisi sapaan. Langkah 3: maksud serta tujuan penulis dituangkan pada bagian isi surat." },
    { q: "Berpidato dengan cara menghafal seluruh naskah terlebih dahulu disebut metode ....", options: ["Impromptu", "Memoriter", "Ekstemporan", "Manuskrip"], answer: 1, solution: "Langkah 1: ingat metode-metode dalam berpidato. Langkah 2: impromptu berarti tanpa persiapan, ekstemporan memakai catatan kecil, dan manuskrip berarti membaca naskah. Langkah 3: menghafal seluruh naskah sebelum berpidato disebut metode memoriter." },
    { q: "Urutan struktur pidato yang tepat adalah ....", options: ["Isi – pembuka – penutup", "Pembuka – isi – penutup", "Penutup – isi – pembuka", "Pembuka – penutup – isi"], answer: 1, solution: "Langkah 1: pidato disampaikan secara runtut dari awal hingga akhir. Langkah 2: bagian awal adalah pembuka yang berisi salam dan pengantar. Langkah 3: dilanjutkan dengan isi sebagai pokok pembicaraan dan diakhiri penutup yang berisi simpulan." },
    { q: "Kalimat berikut yang merupakan opini adalah ....", options: ["Air mendidih pada suhu 100°C.", "Presiden pertama Indonesia adalah Soekarno.", "Membaca adalah hobi yang paling bermanfaat menurut saya.", "Bumi mengelilingi matahari."], answer: 2, solution: "Langkah 1: opini adalah pendapat pribadi yang belum tentu disetujui semua orang. Langkah 2: pilihan A, B, dan D adalah fakta yang dapat dibuktikan kebenarannya. Langkah 3: pilihan C mengandung penilaian pribadi ('menurut saya'), jadi merupakan opini." },
    { q: "Kata hubung yang tepat untuk melengkapi kalimat '... hujan deras, upacara tetap dilaksanakan.' adalah ....", options: ["Meskipun", "Karena", "Sehingga", "Supaya"], answer: 0, solution: "Langkah 1: perhatikan hubungan makna kedua bagian kalimat yang bertentangan. Langkah 2: hujan deras seharusnya menghalangi upacara, tetapi upacara tetap dilaksanakan. Langkah 3: kata hubung yang menyatakan perlawanan adalah 'meskipun'." },
    { q: "Penulisan alamat surat yang tepat adalah ....", options: ["Jalan Mawar No. 10 Bandung", "Jalan Mawar No. 10, Bandung", "Jalan Mawar, No. 10 Bandung", "Jalan, Mawar No. 10 Bandung"], answer: 1, solution: "Langkah 1: ingat kaidah pemakaian tanda koma pada penulisan alamat. Langkah 2: tanda koma dipakai untuk memisahkan nama jalan beserta nomornya dari nama kota. Langkah 3: penulisan yang tepat adalah 'Jalan Mawar No. 10, Bandung'." },
    { q: "Unsur intrinsik yang menggambarkan waktu, tempat, dan suasana dalam sebuah cerita disebut ....", options: ["Tema", "Latar", "Alur", "Amanat"], answer: 1, solution: "Langkah 1: ingat unsur-unsur intrinsik cerita. Langkah 2: tema adalah gagasan pokok, alur adalah jalan cerita, dan amanat adalah pesan moral. Langkah 3: penggambaran waktu, tempat, dan suasana disebut latar." },
    { q: "Pesan moral yang ingin disampaikan pengarang melalui sebuah cerita disebut ....", options: ["Tema", "Amanat", "Sudut pandang", "Gaya bahasa"], answer: 1, solution: "Langkah 1: ingat unsur-unsur intrinsik cerita. Langkah 2: tema adalah ide pokok cerita dan sudut pandang adalah posisi pengarang dalam cerita. Langkah 3: pesan moral atau nasihat yang terkandung dalam cerita disebut amanat." },
    { q: "\"Dimas menemukan sebuah ponsel di taman. Meskipun ia sangat menginginkan ponsel baru, ia memutuskan untuk menyerahkannya ke kantor keamanan.\" Tema kutipan cerpen tersebut adalah ....", options: ["Persahabatan", "Kejujuran", "Keberanian", "Ketekunan"], answer: 1, solution: "Langkah 1: tema adalah gagasan pokok yang menjadi dasar sebuah cerita. Langkah 2: kutipan menceritakan Dimas yang menemukan ponsel dan memilih mengembalikannya meskipun ia menginginkannya. Langkah 3: gagasan pokok cerita tersebut adalah kejujuran." },
    { q: "\"Aku menatap hujan dari balik jendela kamarku. Rasanya aku ingin berlari keluar dan bermain seperti dulu.\" Sudut pandang yang digunakan dalam kutipan cerpen tersebut adalah sudut pandang ....", options: ["Orang pertama", "Orang kedua", "Orang ketiga serba tahu", "Orang ketiga pengamat"], answer: 0, solution: "Langkah 1: sudut pandang menunjukkan posisi pengarang dalam cerita. Langkah 2: kutipan memakai kata ganti \"aku\", yang berarti pengarang menjadi salah satu tokoh cerita. Langkah 3: sudut pandang yang memakai \"aku\" disebut sudut pandang orang pertama." },
    { q: "\"Sekarang ia menjadi pengusaha yang sukses. Namun, sepuluh tahun yang lalu ia hanyalah seorang anak penjual koran yang sering kehujanan di perempatan jalan.\" Alur yang digunakan dalam kutipan cerpen tersebut adalah alur ....", options: ["Maju", "Campuran", "Mundur", "Lurus"], answer: 2, solution: "Langkah 1: alur adalah jalinan peristiwa dalam cerita berdasarkan urutan waktu. Langkah 2: kutipan diawali dari masa kini (\"Sekarang ia menjadi pengusaha yang sukses\") lalu kembali ke masa lalu (\"sepuluh tahun yang lalu\"). Langkah 3: cerita yang bergerak dari masa kini ke masa lalu disebut alur mundur atau sorot balik." },
    { q: "Ciri utama sebuah naskah drama adalah ....", options: ["Didominasi narasi pengarang", "Berisi dialog antartokoh", "Berupa puisi yang bersajak", "Disusun dalam bentuk esai"], answer: 1, solution: "Langkah 1: drama adalah karya sastra yang ditulis untuk dipentaskan. Langkah 2: karena dipentaskan oleh para pemain, naskah drama didominasi oleh percakapan antartokoh. Langkah 3: jadi ciri utama naskah drama adalah berisi dialog antartokoh." },
    { q: "Nadia: \"Maafkan aku, Bu.\" (menangis tersedu-sedu)\nKata dalam tanda kurung pada penggalan naskah drama tersebut disebut ....", options: ["Dialog", "Monolog", "Petunjuk lakuan", "Prolog"], answer: 2, solution: "Langkah 1: naskah drama memuat keterangan tentang gerak atau sikap tokoh. Langkah 2: keterangan tersebut ditulis dalam tanda kurung, misalnya (menangis tersedu-sedu). Langkah 3: keterangan gerak atau laku tokoh dalam tanda kurung disebut petunjuk lakuan." },
    { q: "Perbedaan utama antara drama dan cerpen adalah ....", options: ["Drama selalu lebih panjang daripada cerpen", "Cerpen dipentaskan di atas panggung", "Keduanya tidak memiliki tokoh cerita", "Drama diperankan di atas panggung, sedangkan cerpen dibaca"], answer: 3, solution: "Langkah 1: drama dan cerpen sama-sama karya fiksi yang memiliki tokoh dan alur. Langkah 2: perbedaannya terletak pada cara penyajiannya. Langkah 3: drama ditulis untuk diperankan di atas panggung, sedangkan cerpen ditulis untuk dibaca." },
    { q: "Tujuan utama menulis resensi buku adalah ....", options: ["Memberikan penilaian dan informasi tentang buku sebagai bahan pertimbangan pembaca", "Meringkas seluruh isi buku", "Menyalin ulang isi buku kata demi kata", "Mengiklankan buku dengan bahasa yang persuasif"], answer: 0, solution: "Langkah 1: resensi adalah ulasan atau penilaian terhadap sebuah karya, misalnya buku. Langkah 2: dengan membaca resensi, calon pembaca mendapat gambaran tentang isi serta kualitas buku. Langkah 3: jadi tujuan resensi adalah memberikan penilaian dan informasi tentang buku sebagai bahan pertimbangan pembaca." },
    { q: "Berikut ini yang termasuk unsur-unsur resensi buku adalah ....", options: ["Daftar pustaka, lampiran, dan indeks", "Identitas buku, sinopsis, penilaian kelebihan dan kekurangan", "Orientasi, komplikasi, dan resolusi", "Pembuka, isi, dan penutup surat"], answer: 1, solution: "Langkah 1: resensi yang baik memuat bagian-bagian yang lengkap. Langkah 2: bagian-bagian tersebut meliputi identitas buku (judul, pengarang, penerbit), sinopsis atau ringkasan isi, serta penilaian kelebihan dan kekurangan buku. Langkah 3: jadi unsur-unsur resensi adalah identitas buku, sinopsis, dan penilaian kelebihan serta kekurangan." },
    { q: "Ciri teks editorial atau tajuk rencana adalah ....", options: ["Berisi kisah khayalan yang menghibur pembaca", "Berupa laporan hasil pengamatan di lapangan", "Berisi tanggapan redaksi terhadap peristiwa aktual yang bersifat argumentatif", "Berisi petunjuk melakukan sesuatu langkah demi langkah"], answer: 2, solution: "Langkah 1: teks editorial ditulis oleh redaksi sebuah media massa. Langkah 2: isinya berupa tanggapan atau pendapat redaksi terhadap peristiwa aktual yang sedang hangat dibicarakan. Langkah 3: karena berisi pendapat yang disertai alasan, teks editorial bersifat argumentatif." },
    { q: "Fungsi teks editorial bagi pembaca adalah ....", options: ["Memberikan petunjuk cara membuat sesuatu", "Mengiklankan produk tertentu", "Menceritakan pengalaman pribadi penulis", "Menyatakan sikap media terhadap suatu peristiwa agar pembaca memperoleh sudut pandang baru"], answer: 3, solution: "Langkah 1: teks editorial memuat pendapat redaksi tentang suatu peristiwa. Langkah 2: pendapat tersebut disampaikan agar pembaca ikut memikirkan dan menilai peristiwa itu. Langkah 3: jadi fungsinya adalah menyatakan sikap media terhadap suatu peristiwa agar pembaca memperoleh sudut pandang baru." },
    { q: "Ciri bahasa yang digunakan dalam iklan adalah ....", options: ["Singkat, menarik, dan persuasif", "Panjang dan berbelit-belit", "Formal dan kaku", "Penuh dengan istilah ilmiah"], answer: 0, solution: "Langkah 1: iklan bertujuan memengaruhi pembaca agar tertarik pada produk atau jasa. Langkah 2: agar pesan cepat ditangkap, bahasa iklan dibuat singkat dan menarik. Langkah 3: bahasa yang bersifat membujuk disebut persuasif, jadi ciri bahasa iklan adalah singkat, menarik, dan persuasif." },
    { q: "Kalimat berikut yang termasuk kalimat persuasif dalam iklan adalah ....", options: ["\"Sabun ini berwarna putih.\"", "\"Toko buka setiap hari.\"", "\"Jangan lewatkan kesempatan emas ini, segera dapatkan sekarang juga!\"", "\"Produk ini dikemas dalam kotak.\""], answer: 2, solution: "Langkah 1: kalimat persuasif bertujuan membujuk atau mengajak pembaca melakukan sesuatu. Langkah 2: pilihan A, B, dan D hanya menyampaikan informasi biasa. Langkah 3: pilihan C memakai ajakan yang mendesak (\"Jangan lewatkan ... segera dapatkan\"), jadi merupakan kalimat persuasif." },
    { q: "Urutan struktur teks laporan hasil observasi yang tepat adalah ....", options: ["Pernyataan umum – deskripsi bagian – deskripsi manfaat", "Orientasi – komplikasi – resolusi", "Tesis – argumen – penegasan ulang", "Identifikasi – deskripsi bagian – simpulan"], answer: 0, solution: "Langkah 1: ingat struktur teks laporan hasil observasi. Langkah 2: teks diawali pernyataan umum yang berisi gambaran umum objek, dilanjutkan deskripsi bagian yang memerinci ciri-ciri objek, dan diakhiri deskripsi manfaat. Langkah 3: jadi urutan yang tepat adalah pernyataan umum – deskripsi bagian – deskripsi manfaat." },
    { q: "Bagian \"deskripsi bagian\" dalam teks laporan hasil observasi berisi ....", options: ["Gambaran umum tentang objek yang diamati", "Rincian ciri-ciri dan sifat-sifat objek yang diamati", "Kesimpulan hasil pengamatan", "Tanggapan penulis terhadap objek"], answer: 1, solution: "Langkah 1: ingat fungsi tiap bagian teks laporan hasil observasi. Langkah 2: pernyataan umum berisi gambaran umum, sedangkan bagian penutup berisi simpulan atau manfaat. Langkah 3: rincian ciri-ciri dan sifat-sifat objek yang diamati terdapat pada bagian deskripsi bagian." },
    { q: "Bacalah puisi berikut!\n\"Di bawah langit senja yang merah\naku menatap jejak langkahmu\nyang perlahan hilang ditelan gelap.\"\nTema puisi tersebut adalah ....", options: ["Kemarahan", "Keberanian", "Kebahagiaan", "Kerinduan"], answer: 3, solution: "Langkah 1: tema adalah gagasan pokok yang terkandung dalam puisi. Langkah 2: larik \"aku menatap jejak langkahmu yang perlahan hilang ditelan gelap\" menggambarkan seseorang yang ditinggalkan oleh orang yang dicintainya. Langkah 3: perasaan yang tergambar adalah kerinduan terhadap seseorang yang telah pergi." },
    { q: "\"Aroma tanah basah menyeruak seusai hujan.\" Citraan yang dominan dalam larik puisi tersebut adalah citraan ....", options: ["Penciuman", "Penglihatan", "Pendengaran", "Perabaan"], answer: 0, solution: "Langkah 1: citraan adalah gambaran yang membangkitkan kesan indra pembaca. Langkah 2: kata \"aroma\" berkaitan dengan indra penciuman atau bau-bauan. Langkah 3: jadi larik tersebut memakai citraan penciuman." },
    { q: "Kata serapan yang tepat dari bahasa Inggris \"organization\" adalah ....", options: ["Organisassi", "Organisasi", "Organsasi", "Oraganisasi"], answer: 1, solution: "Langkah 1: kata serapan adalah kata yang diambil dari bahasa lain dan disesuaikan dengan kaidah bahasa Indonesia. Langkah 2: akhiran \"-tion\" dalam bahasa Inggris umumnya diserap menjadi \"-si\", misalnya \"organization\" menjadi \"organisasi\". Langkah 3: jadi bentuk serapan yang tepat adalah \"organisasi\"." },
    { q: "Kalimat berikut yang menggunakan konjungsi antarkalimat adalah ....", options: ["Dia belajar dengan giat karena ingin lulus.", "Meskipun lelah, ia tetap berlatih.", "Hujan turun sangat deras. Oleh karena itu, pertandingan ditunda.", "Ayah dan ibu pergi ke pasar."], answer: 2, solution: "Langkah 1: konjungsi antarkalimat menghubungkan dua kalimat dan selalu ditulis di awal kalimat. Langkah 2: pilihan A, B, dan D memakai kata hubung di dalam satu kalimat (intrakalimat). Langkah 3: \"Oleh karena itu\" menghubungkan kalimat kedua dengan kalimat pertama, jadi merupakan konjungsi antarkalimat." },
    { q: "\"Ayah membaca koran, sedangkan ibu memasak di dapur.\" Kalimat tersebut termasuk kalimat majemuk ....", options: ["Tunggal", "Bertingkat", "Campuran", "Setara"], answer: 3, solution: "Langkah 1: kalimat majemuk setara terdiri atas dua klausa atau lebih yang kedudukannya sejajar. Langkah 2: \"Ayah membaca koran\" dan \"ibu memasak di dapur\" sama-sama dapat berdiri sendiri dan dihubungkan kata \"sedangkan\". Langkah 3: jadi kalimat tersebut termasuk kalimat majemuk setara." },
    { q: "\"Siswa yang rajin berlatih itu akhirnya meraih juara.\" Kalimat tersebut termasuk kalimat majemuk ....", options: ["Bertingkat", "Setara", "Tunggal", "Intransitif"], answer: 0, solution: "Langkah 1: kalimat majemuk bertingkat terdiri atas klausa utama dan anak klausa. Langkah 2: bagian \"yang rajin berlatih\" tidak dapat berdiri sendiri dan hanya menjelaskan kata \"siswa\", sehingga merupakan anak klausa. Langkah 3: jadi kalimat tersebut termasuk kalimat majemuk bertingkat." },
{ q: "Perhatikan kutipan berikut. \"Pada suatu pagi yang cerah, Andi berangkat ke sekolah dengan sepeda barunya. Ia tinggal di sebuah desa kecil di kaki gunung.\" Kutipan tersebut merupakan bagian struktur teks narasi yang disebut...", options: ["orientasi", "komplikasi", "resolusi", "koda"], answer: 0, solution: "1. Kutipan memperkenalkan tokoh (Andi), latar waktu (pagi yang cerah), dan latar tempat (desa kecil). 2. Bagian teks narasi yang berisi pengenalan tokoh, latar, dan situasi awal disebut orientasi. 3. Komplikasi berisi konflik, resolusi berisi penyelesaian, dan koda berisi pesan penutup." },
{ q: "Bagian teks narasi yang berisi rangkaian permasalahan atau konflik yang dialami tokoh disebut...", options: ["resolusi", "orientasi", "koda", "komplikasi"], answer: 3, solution: "1. Konflik adalah inti permasalahan yang membuat cerita bergerak dan menarik. 2. Bagian yang memuat rangkaian konflik atau permasalahan disebut komplikasi. 3. Orientasi berisi pengenalan, resolusi berisi penyelesaian, dan koda berisi penutup." },
{ q: "\"Akhirnya, Budi meminta maaf kepada Sinta dan mereka berbaikan kembali.\" Kalimat tersebut menunjukkan bagian struktur narasi berupa...", options: ["orientasi", "komplikasi", "resolusi", "pengenalan"], answer: 2, solution: "1. Kalimat menunjukkan masalah antara Budi dan Sinta telah selesai karena mereka berbaikan. 2. Bagian yang berisi penyelesaian konflik disebut resolusi. 3. Orientasi dan pengenalan ada di awal cerita, sedangkan komplikasi berisi masalah." },
{ q: "Bagian penutup teks narasi yang berisi pesan atau pelajaran dari pengarang disebut...", options: ["tesis", "koda", "klimaks", "argumen"], answer: 1, solution: "1. Pesan atau pelajaran pengarang biasanya disampaikan di akhir cerita. 2. Bagian penutup narasi yang memuat pesan tersebut disebut koda. 3. Tesis dan argumen adalah bagian teks eksposisi, sedangkan klimaks adalah puncak alur." },
{ q: "Teks narasi yang menceritakan kejadian nyata, seperti biografi dan autobiografi, disebut narasi...", options: ["fiktif", "sugestif", "nonfiksi", "imajinatif"], answer: 2, solution: "1. Biografi dan autobiografi menceritakan kisah hidup yang benar-benar terjadi. 2. Narasi yang berdasarkan fakta atau kejadian nyata disebut narasi nonfiksi. 3. Narasi fiktif atau imajinatif justru berasal dari khayalan pengarang." },
{ q: "Narasi yang bertujuan memengaruhi pembaca secara emosional dan bersifat imajinatif disebut narasi...", options: ["ekspositoris", "informatif", "faktual", "sugestif"], answer: 3, solution: "1. Narasi jenis ini membangkitkan emosi dan imajinasi pembaca, bukan sekadar memberi fakta. 2. Narasi yang bersifat demikian disebut narasi sugestif atau artistik. 3. Narasi ekspositoris, informatif, dan faktual menyampaikan informasi secara objektif." },
{ q: "Ciri utama teks narasi adalah...", options: ["memaparkan pendapat dengan argumen", "menceritakan rangkaian peristiwa secara runtut", "menggambarkan objek secara detail", "membujuk pembaca untuk bertindak"], answer: 1, solution: "1. Kata narasi berasal dari narration yang artinya bercerita. 2. Ciri utamanya adalah menceritakan rangkaian peristiwa yang disusun runtut mengikuti waktu. 3. Pilihan lain adalah ciri eksposisi, deskripsi, dan persuasi." },
{ q: "Urutan struktur teks narasi yang tepat adalah...", options: ["tesis-argumen-penegasan ulang", "identifikasi-deskripsi-simpulan", "orientasi-komplikasi-resolusi", "pembuka-isi-penutup pidato"], answer: 2, solution: "1. Teks narasi selalu diawali dengan pengenalan sebelum masuk ke masalah. 2. Urutan yang tepat adalah orientasi (pengenalan), komplikasi (konflik), resolusi (penyelesaian). 3. Pilihan lain adalah struktur eksposisi, deskripsi, dan pidato." },
{ q: "Narasi ekspositoris berbeda dengan narasi sugestif karena narasi ekspositoris...", options: ["menyampaikan informasi secara objektif", "penuh imajinasi pengarang", "bertujuan menghibur pembaca", "menggunakan bahasa kiasan"], answer: 0, solution: "1. Kata ekspositoris berasal dari eksposisi yang berarti paparan. 2. Narasi ekspositoris menyampaikan fakta dan informasi apa adanya secara objektif. 3. Imajinasi, hiburan, dan bahasa kiasan adalah ciri narasi sugestif." },
{ q: "\"Setelah kejadian itu, Rina tidak pernah lagi mengambil barang milik temannya.\" Fungsi kalimat tersebut dalam struktur narasi adalah sebagai...", options: ["orientasi", "komplikasi", "tesis", "koda"], answer: 3, solution: "1. Kalimat menyampaikan pelajaran yang dipetik tokoh dari peristiwa yang dialaminya. 2. Pelajaran atau pesan di akhir narasi berfungsi sebagai koda. 3. Orientasi ada di awal, komplikasi berisi konflik, dan tesis milik eksposisi." },
{ q: "Bagian teks eksposisi yang berisi pendapat atau gagasan utama penulis di awal teks disebut...", options: ["argumen", "tesis", "penegasan ulang", "simpulan"], answer: 1, solution: "1. Penulis perlu menyampaikan posisi atau gagasannya di awal agar pembaca paham arah tulisan. 2. Bagian yang berisi pendapat utama di awal disebut tesis. 3. Argumen adalah bukti pendukung, sedangkan penegasan ulang ada di akhir." },
{ q: "Fungsi argumen dalam teks eksposisi adalah...", options: ["mengulang pendapat penulis", "menutup teks dengan simpulan", "memperkuat tesis dengan bukti dan alasan", "memperkenalkan topik"], answer: 2, solution: "1. Tesis saja belum cukup meyakinkan tanpa dukungan yang kuat. 2. Argumen berfungsi memperkuat tesis dengan data, fakta, dan alasan yang logis. 3. Mengulang pendapat dan menutup teks adalah fungsi penegasan ulang." },
{ q: "Bagian akhir teks eksposisi yang menegaskan kembali pendapat penulis disebut...", options: ["tesis", "orientasi", "koda", "penegasan ulang"], answer: 3, solution: "1. Setelah menyampaikan argumen, penulis perlu menutup tulisan dengan penguatan pendapat. 2. Bagian akhir ini disebut penegasan ulang atau reiterasi. 3. Tesis ada di awal, sedangkan orientasi dan koda adalah bagian teks narasi." },
{ q: "\"Fotosintesis adalah proses tumbuhan hijau mengubah cahaya matahari menjadi energi kimia.\" Teks tersebut termasuk eksposisi jenis...", options: ["definisi", "proses", "perbandingan", "ilustrasi"], answer: 0, solution: "1. Kalimat menjelaskan pengertian atau makna suatu istilah. 2. Eksposisi yang menjelaskan pengertian disebut eksposisi definisi. 3. Eksposisi proses berisi tahapan, perbandingan berisi persamaan-perbedaan." },
{ q: "Teks eksposisi yang menjelaskan tahap demi tahap cara membuat atau melakukan sesuatu disebut eksposisi...", options: ["definisi", "klasifikasi", "proses", "perbandingan"], answer: 2, solution: "1. Teks memaparkan langkah-langkah yang berurutan. 2. Jenis eksposisi yang berisi tahapan atau langkah disebut eksposisi proses. 3. Definisi berisi pengertian, klasifikasi berisi pengelompokan." },
{ q: "\"Berbeda dengan sepeda motor, sepeda listrik tidak menghasilkan asap knalpot sehingga lebih ramah lingkungan.\" Teks tersebut termasuk eksposisi jenis...", options: ["definisi", "perbandingan", "proses", "laporan"], answer: 1, solution: "1. Teks membandingkan dua objek, yaitu sepeda motor dan sepeda listrik. 2. Eksposisi yang memaparkan persamaan atau perbedaan dua hal disebut eksposisi perbandingan. 3. Teks ini tidak menjelaskan pengertian ataupun tahapan." },
{ q: "Eksposisi ilustrasi ditandai dengan...", options: ["pengulangan pendapat di akhir", "urutan waktu kejadian", "dialog antar tokoh", "pemberian contoh-contoh konkret"], answer: 3, solution: "1. Kata ilustrasi berarti penggambaran melalui contoh. 2. Eksposisi ilustrasi menjelaskan gagasan dengan contoh-contoh konkret agar mudah dipahami. 3. Pengulangan pendapat adalah ciri penegasan ulang, bukan ilustrasi." },
{ q: "Berikut ini yang BUKAN struktur teks eksposisi adalah...", options: ["komplikasi", "tesis", "argumen", "penegasan ulang"], answer: 0, solution: "1. Struktur teks eksposisi hanya terdiri dari tiga bagian. 2. Komplikasi adalah bagian teks narasi yang berisi konflik, bukan bagian eksposisi. 3. Tesis, argumen, dan penegasan ulang adalah tiga struktur teks eksposisi." },
{ q: "Unsur 5W+1H dalam teks berita terdiri atas...", options: ["who, whom, whose, which, what, when", "what, why, where, when, with, whom", "what, who, where, when, why, how", "who, what, where, when, why, whom"], answer: 2, solution: "1. Berita yang baik harus menjawab pertanyaan-pertanyaan dasar jurnalistik. 2. Unsur 5W+1H adalah what, who, where, when, why, ditambah how. 3. Whom, whose, dan with bukan bagian dari unsur 5W+1H." },
{ q: "Dalam unsur 5W+1H, kata tanya \"why\" menanyakan tentang...", options: ["siapa yang terlibat", "alasan atau penyebab peristiwa", "kapan peristiwa terjadi", "bagaimana peristiwa terjadi"], answer: 1, solution: "1. Setiap unsur 5W+1H menanyakan aspek peristiwa yang berbeda. 2. Why menanyakan mengapa, yaitu alasan atau penyebab terjadinya peristiwa. 3. Siapa adalah who, kapan adalah when, dan bagaimana adalah how." },
{ q: "Unsur \"how\" dalam teks berita memuat informasi tentang...", options: ["pelaku peristiwa", "lokasi kejadian", "waktu kejadian", "cara atau proses terjadinya peristiwa"], answer: 3, solution: "1. How adalah unsur pelengkap setelah 5W yang menanyakan cara. 2. Unsur how memuat cara atau proses terjadinya peristiwa. 3. Pelaku adalah who, lokasi adalah where, dan waktu adalah when." },
{ q: "Pola piramida terbalik dalam teks berita berarti...", options: ["informasi disusun dari yang terpenting ke kurang penting", "peristiwa diceritakan dari akhir ke awal", "berita ditulis dari sudut pandang pelaku", "fakta disusun berdasarkan urutan waktu"], answer: 0, solution: "1. Pembaca berita ingin segera mengetahui inti peristiwa tanpa membaca seluruh teks. 2. Piramida terbalik berarti informasi terpenting diletakkan di awal, makin ke bawah makin kurang penting. 3. Pola ini bukan urutan waktu ataupun sudut pandang pelaku." },
{ q: "Bagian pembuka teks berita yang memuat inti peristiwa secara ringkas disebut...", options: ["tubuh berita", "ekor berita", "kepala berita (lead)", "judul berita"], answer: 2, solution: "1. Pembuka berita merangkum unsur 5W+1H secara singkat dan padat. 2. Bagian ini disebut kepala berita atau lead, juga dikenal sebagai teras berita. 3. Tubuh berita berisi rincian, ekor berita berisi info tambahan." },
{ q: "Bahasa yang digunakan dalam teks berita sebaiknya...", options: ["berbunga-bunga dan penuh kiasan", "lugas, singkat, dan jelas", "panjang dan bertele-tele", "subjektif dan emosional"], answer: 1, solution: "1. Berita harus bisa dipahami dengan cepat oleh semua kalangan pembaca. 2. Bahasa berita bersifat lugas, singkat, jelas, dan objektif. 3. Bahasa kiasan, bertele-tele, dan emosional tidak cocok untuk berita." },
{ q: "Judul berita yang baik harus...", options: ["panjang dan detail", "penuh singkatan", "menggunakan bahasa daerah", "singkat, menarik, dan mewakili isi"], answer: 3, solution: "1. Judul adalah pintu masuk yang menentukan pembaca mau membaca berita atau tidak. 2. Judul yang baik singkat, menarik perhatian, dan mewakili isi berita. 3. Judul yang panjang dan detail justru membuat pembaca bosan." },
{ q: "Sumber berita harus jelas dan dapat dipertanggungjawabkan agar...", options: ["kebenaran berita dapat dipercaya", "berita terlihat panjang", "bahasa berita indah", "berita cepat selesai ditulis"], answer: 0, solution: "1. Berita tanpa sumber yang jelas rawan menjadi kabar bohong atau hoaks. 2. Sumber yang jelas membuat kebenaran berita dapat dipercaya dan dipertanggungjawabkan. 3. Panjang berita dan keindahan bahasa bukan tujuan pencantuman sumber." },
{ q: "Gagasan pokok yang mendasari keseluruhan cerita dalam cerpen disebut...", options: ["amanat", "alur", "tema", "sudut pandang"], answer: 2, solution: "1. Setiap cerita dibangun dari satu gagasan dasar yang menjiwai seluruh peristiwa. 2. Gagasan pokok tersebut disebut tema. 3. Amanat adalah pesan, alur adalah jalan cerita, dan sudut pandang adalah posisi pencerita." },
{ q: "Tokoh yang paling banyak berperan dan menjadi pusat perhatian dalam cerpen disebut tokoh...", options: ["tambahan", "utama", "figuran", "pembantu"], answer: 1, solution: "1. Cerpen berputar di sekitar satu tokoh sentral yang paling sering muncul. 2. Tokoh sentral tersebut disebut tokoh utama. 3. Tokoh tambahan, figuran, dan pembantu hanya berperan sebagai pelengkap." },
{ q: "\"Ia adalah anak yang rajin, jujur, dan tidak pernah berbohong.\" Penggambaran watak tokoh secara langsung oleh pengarang seperti itu disebut penokohan...", options: ["dramatik", "tidak langsung", "tersirat", "analitik"], answer: 3, solution: "1. Pengarang menjelaskan sifat tokoh secara eksplisit tanpa perantara. 2. Penjelasan watak secara langsung oleh pengarang disebut penokohan analitik. 3. Penokohan dramatik justru lewat dialog dan perilaku tokoh." },
{ q: "Watak tokoh yang diketahui pembaca melalui dialog, perbuatan, dan tingkah laku tokoh itu sendiri disebut penokohan...", options: ["dramatik", "analitik", "langsung", "eksplisit"], answer: 0, solution: "1. Pembaca menyimpulkan sendiri sifat tokoh dari tindakan dan ucapannya. 2. Cara penggambaran watak secara tidak langsung ini disebut penokohan dramatik. 3. Penokohan analitik adalah penjelasan langsung oleh pengarang." },
{ q: "Alur yang menceritakan peristiwa secara berurutan dari awal hingga akhir mengikuti waktu disebut alur...", options: ["mundur", "campuran", "maju", "sorot balik"], answer: 2, solution: "1. Peristiwa berjalan ke depan mengikuti urutan waktu yang kronologis. 2. Alur kronologis ke depan disebut alur maju atau progresif. 3. Alur mundur bergerak ke masa lalu, sedangkan campuran menggabungkan keduanya." },
{ q: "Cerpen yang diawali peristiwa masa kini lalu menceritakan kembali kejadian masa lalu menggunakan alur...", options: ["maju", "mundur", "campuran", "linear"], answer: 1, solution: "1. Cerita bergerak ke belakang waktu untuk mengisahkan kejadian yang sudah lewat. 2. Alur yang bergerak ke masa lalu disebut alur mundur atau regresif, juga dikenal sebagai flashback. 3. Alur maju bergerak kronologis ke depan." },
{ q: "Alur campuran dalam cerpen ditandai dengan...", options: ["cerita hanya bergerak maju", "cerita tanpa konflik", "peristiwa acak tanpa urutan", "gabungan alur maju dan alur mundur"], answer: 3, solution: "1. Sebagian cerpen memakai kilas balik di tengah jalan cerita yang bergerak maju. 2. Gabungan alur maju dan alur mundur disebut alur campuran. 3. Alur campuran tetap memiliki konflik dan urutan yang jelas." },
{ q: "Tahapan alur yang berisi pengenalan tokoh, latar, dan situasi awal cerita disebut tahap...", options: ["pengenalan", "klimaks", "penyelesaian", "konflik memuncak"], answer: 0, solution: "1. Pembaca perlu dikenalkan dengan tokoh dan situasi sebelum konflik muncul. 2. Tahap awal ini disebut pengenalan atau eksposisi. 3. Klimaks adalah puncak konflik, sedangkan penyelesaian ada di akhir." },
{ q: "Bagian alur yang merupakan puncak ketegangan konflik dalam cerita disebut...", options: ["pengenalan", "resolusi", "klimaks", "pemunculan konflik"], answer: 2, solution: "1. Konflik dalam cerita memuncak pada satu titik ketegangan tertinggi. 2. Titik puncak tersebut disebut klimaks. 3. Pengenalan ada di awal, pemunculan konflik sebelum klimaks, dan resolusi sesudahnya." },
{ q: "Tahapan alur setelah klimaks yang berisi menurunnya ketegangan menuju akhir cerita disebut...", options: ["pengenalan", "penyelesaian", "pemunculan konflik", "komplikasi"], answer: 1, solution: "1. Setelah mencapai puncak, ketegangan cerita mulai menurun dan masalah menemukan jalan keluar. 2. Tahap ini disebut penyelesaian, resolusi, atau antiklimaks. 3. Pengenalan dan pemunculan konflik berada sebelum klimaks." },
{ q: "\"Aku berjalan menyusuri gang sempit itu dengan jantung berdebar.\" Sudut pandang yang digunakan dalam kutipan tersebut adalah orang...", options: ["ketiga serbatahu", "kedua", "ketiga terbatas", "pertama pelaku utama"], answer: 3, solution: "1. Pencerita menggunakan kata ganti aku dan terlibat langsung dalam peristiwa. 2. Sudut pandang dengan pencerita sebagai tokoh utama disebut orang pertama pelaku utama. 3. Sudut pandang orang ketiga menggunakan kata ganti dia atau mereka." },
{ q: "Sudut pandang orang pertama sampingan berarti pencerita...", options: ["bukan tokoh utama tetapi terlibat dalam cerita", "tokoh utama cerita", "pengamat yang tahu segalanya", "pembaca cerita"], answer: 0, solution: "1. Pencerita memakai kata ganti aku namun bukan pusat perhatian cerita. 2. Ia adalah tokoh sampingan yang menyaksikan kisah tokoh utama, disebut orang pertama sampingan. 3. Pengamat yang tahu segalanya adalah sudut pandang orang ketiga serbatahu." },
{ q: "Pengarang yang menceritakan isi hati dan pikiran semua tokoh dalam cerpen menggunakan sudut pandang orang ketiga...", options: ["terbatas", "tunggal", "serbatahu", "sampingan"], answer: 2, solution: "1. Pengarang mengetahui segalanya, termasuk perasaan setiap tokoh. 2. Sudut pandang ini disebut orang ketiga serbatahu atau mahatahu. 3. Sudut pandang terbatas hanya mengetahui isi hati satu tokoh tertentu." },
{ q: "Dalam sudut pandang orang ketiga terbatas, pengarang hanya...", options: ["mengetahui pikiran semua tokoh", "mengetahui pikiran satu tokoh tertentu", "menjadi tokoh utama", "berdialog dengan pembaca"], answer: 1, solution: "1. Kata terbatas menunjukkan pengetahuan pengarang dibatasi. 2. Pengarang hanya mengetahui isi hati dan pikiran satu tokoh tertentu. 3. Mengetahui pikiran semua tokoh adalah ciri sudut pandang serbatahu." },
{ q: "Pilihan kata dan cara berbahasa khas yang digunakan pengarang dalam cerpen disebut...", options: ["tema", "sudut pandang", "gaya bahasa", "amanat"], answer: 2, solution: "1. Setiap pengarang memiliki ciri khas dalam memilih dan merangkai kata. 2. Ciri khas berbahasa tersebut disebut gaya bahasa atau style. 3. Tema adalah gagasan pokok, sedangkan sudut pandang adalah posisi pencerita." },
{ q: "Tokoh yang menentang atau menjadi lawan tokoh utama dalam cerita disebut tokoh...", options: ["protagonis", "tritagonis", "figuran", "antagonis"], answer: 3, solution: "1. Lawan tokoh utama inilah yang menciptakan konflik dalam cerita. 2. Tokoh penentang tersebut disebut antagonis. 3. Protagonis adalah tokoh utama, sedangkan figuran hanya pelengkap." },
{ q: "Pertentangan antara dua kekuatan dalam cerita yang membuat cerita menjadi menarik disebut...", options: ["konflik", "tema", "resolusi", "klimaks"], answer: 0, solution: "1. Tanpa pertentangan, cerita akan terasa datar dan membosankan. 2. Pertentangan antara dua kekuatan disebut konflik. 3. Klimaks adalah puncak konflik, sedangkan resolusi adalah penyelesaiannya." },
{ q: "Perbedaan tokoh dan penokohan adalah...", options: ["tokoh adalah watak, penokohan adalah pelaku", "tokoh adalah pelaku, penokohan adalah cara pengarang menggambarkan watak tokoh", "keduanya sama saja", "tokoh di awal, penokohan di akhir"], answer: 1, solution: "1. Tokoh menjawab pertanyaan siapa yang berperan, penokohan menjawab bagaimana wataknya. 2. Jadi tokoh adalah pelaku cerita, sedangkan penokohan adalah cara pengarang menggambarkan watak tokoh. 3. Keduanya adalah unsur intrinsik yang berbeda." },
{ q: "Tahapan alur ketika masalah mulai muncul dan menimpa tokoh disebut tahap...", options: ["pengenalan", "klimaks", "pemunculan konflik", "penyelesaian"], answer: 2, solution: "1. Setelah pengenalan, cerita membutuhkan masalah agar bergerak maju. 2. Tahap munculnya masalah disebut pemunculan konflik atau rising action. 3. Klimaks adalah puncak masalah, sedangkan penyelesaian ada di akhir." },
{ q: "\"Hadir dalam acara itu bupati, camat, lurah, ketua RW, hingga ketua RT.\" Majas yang digunakan pada kalimat tersebut adalah...", options: ["klimaks", "repetisi", "paradoks", "antiklimaks"], answer: 3, solution: "1. Jabatan-jabatan disusun bertingkat dari yang tinggi ke yang rendah. 2. Susunan yang bertingkat turun disebut majas antiklimaks. 3. Klimaks adalah kebalikannya, yaitu susunan bertingkat naik." },
{ q: "Unsur ekstrinsik cerpen adalah unsur yang...", options: ["di luar cerita yang memengaruhi karya", "di dalam cerita seperti tema dan alur", "hanya berupa gaya bahasa", "menjadi bagian penutup cerita"], answer: 0, solution: "1. Kata ekstrinsik berarti berada di luar. 2. Unsur ekstrinsik adalah faktor di luar cerita yang memengaruhi karya, misalnya latar belakang pengarang. 3. Tema, alur, dan gaya bahasa adalah unsur intrinsik." },
{ q: "Contoh unsur ekstrinsik dalam cerpen adalah...", options: ["alur dan penokohan", "latar belakang sosial pengarang", "tema dan amanat", "sudut pandang"], answer: 1, solution: "1. Kehidupan dan lingkungan pengarang ikut memengaruhi isi karyanya. 2. Latar belakang sosial pengarang termasuk unsur ekstrinsik. 3. Alur, tema, dan sudut pandang adalah unsur intrinsik." },
{ q: "Nilai moral dalam cerpen berkaitan dengan...", options: ["keindahan bahasa", "adat istiadat masyarakat", "ajaran baik dan buruk tentang perilaku manusia", "kehebatan tokoh"], answer: 2, solution: "1. Moral berhubungan dengan etika dan perilaku manusia. 2. Nilai moral adalah ajaran tentang baik dan buruknya perilaku manusia dalam cerita. 3. Adat istiadat berkaitan dengan nilai budaya, bukan nilai moral." },
{ q: "Nilai budaya dalam cerpen tercermin melalui...", options: ["pilihan kata pengarang", "jumlah tokoh", "panjang pendek cerita", "adat istiadat dan kebiasaan masyarakat dalam cerita"], answer: 3, solution: "1. Budaya suatu masyarakat tampak dari cara hidupnya sehari-hari. 2. Nilai budaya tercermin lewat adat istiadat dan kebiasaan masyarakat yang digambarkan dalam cerita. 3. Pilihan kata adalah gaya bahasa yang termasuk unsur intrinsik." },
{ q: "Ciri umum puisi lama adalah...", options: ["bebas tanpa aturan", "terikat aturan jumlah baris, suku kata, dan rima", "selalu berbahasa Inggris", "tidak memiliki tema"], answer: 1, solution: "1. Puisi lama diwariskan turun-temurun dengan pakem yang ketat. 2. Cirinya adalah terikat aturan, seperti jumlah baris, suku kata, dan rima. 3. Puisi yang bebas tanpa aturan adalah puisi baru." },
{ q: "Karmina memiliki ciri...", options: ["terdiri dari dua baris bersajak a-a", "terdiri dari empat baris bersajak a-b-a-b", "terdiri dari delapan baris", "bebas jumlah baris"], answer: 0, solution: "1. Karmina disebut juga pantun kilat karena bentuknya sangat pendek. 2. Cirinya adalah terdiri dari dua baris (sepasang) yang bersajak a-a. 3. Empat baris bersajak a-b-a-b adalah ciri pantun." },
{ q: "Pada karmina, baris pertama berfungsi sebagai sampiran dan baris kedua berfungsi sebagai...", options: ["sampiran juga", "judul", "isi", "rima"], answer: 2, solution: "1. Karmina hanya memiliki dua baris dengan fungsi yang berbeda. 2. Baris pertama sebagai sampiran (pengantar), baris kedua sebagai isi (maksud). 3. Keduanya tidak memiliki fungsi yang sama." },
{ q: "Seloka adalah puisi lama yang...", options: ["terdiri dari satu bait saja", "terdiri dari beberapa bait pantun yang saling berkaitan", "hanya dua baris", "tanpa rima"], answer: 1, solution: "1. Seloka berbentuk rangkaian bait yang berkesinambungan. 2. Seloka terdiri dari beberapa bait berbentuk pantun yang isinya saling berkaitan. 3. Seloka bukan satu bait, bukan dua baris, dan tetap memakai rima." },
{ q: "Setiap bait seloka terdiri atas...", options: ["dua baris", "enam baris", "delapan baris", "empat baris"], answer: 3, solution: "1. Seloka memakai bentuk pantun untuk setiap baitnya. 2. Setiap bait seloka terdiri dari empat baris seperti pantun. 3. Dua baris adalah karmina, sedangkan enam atau delapan baris adalah talibun." },
{ q: "Talibun adalah puisi lama yang jumlah barisnya...", options: ["genap seperti enam, delapan, atau sepuluh", "selalu empat", "selalu ganjil", "bebas"], answer: 0, solution: "1. Talibun lebih panjang daripada pantun biasa. 2. Jumlah baris talibun selalu genap, yaitu enam, delapan, atau sepuluh baris. 3. Empat baris adalah pantun, bukan talibun." },
{ q: "Dalam talibun, separuh baris awal berfungsi sebagai sampiran dan separuh baris akhir berfungsi sebagai...", options: ["sampiran", "judul", "isi", "penutup"], answer: 2, solution: "1. Talibun mengikuti pola pantun yang diperpanjang. 2. Separuh baris awal sebagai sampiran, separuh baris akhir sebagai isi. 3. Pola sampiran-isi ini konsisten pada talibun." },
{ q: "Puisi lama umumnya bersifat anonim, artinya...", options: ["ditulis banyak orang", "pengarangnya tidak diketahui", "tanpa judul", "tanpa rima"], answer: 1, solution: "1. Puisi lama diwariskan secara lisan dari generasi ke generasi. 2. Anonim berarti pengarang atau penciptanya tidak diketahui. 3. Anonim tidak berarti tanpa judul atau tanpa rima." },
{ q: "Perbedaan utama pantun dan karmina terletak pada...", options: ["bahasa yang digunakan", "tema ceritanya", "nama pengarangnya", "jumlah barisnya"], answer: 3, solution: "1. Pantun terdiri dari empat baris, sedangkan karmina hanya dua baris. 2. Perbedaan utama keduanya adalah jumlah baris. 3. Keduanya sama-sama puisi lama berbahasa Melayu dengan tema yang beragam." },
{ q: "Sebuah puisi lama terdiri dari delapan baris dengan separuh awal sebagai sampiran dan separuh akhir sebagai isi. Puisi tersebut termasuk jenis...", options: ["talibun", "pantun", "karmina", "seloka"], answer: 0, solution: "1. Cirinya adalah delapan baris yang genap dengan pola sampiran-isi. 2. Puisi lama dengan ciri tersebut adalah talibun. 3. Pantun empat baris, karmina dua baris, dan seloka berbentuk bait-bait." },
{ q: "Puisi baru yang menceritakan kisah hidup atau perjuangan seseorang secara naratif disebut...", options: ["ode", "himne", "balada", "elegi"], answer: 2, solution: "1. Puisi ini berisi cerita tentang pengalaman hidup seseorang. 2. Puisi naratif tentang kisah hidup disebut balada. 3. Ode berisi pujian pahlawan, himne berisi pujian Tuhan, dan elegi berisi duka cita." },
{ q: "Himne adalah puisi yang berisi...", options: ["pujian kepada Tuhan, dewa, atau tanah air", "sindiran sosial", "ratapan duka cita", "kisah percintaan"], answer: 0, solution: "1. Himne bernada agung, khidmat, dan penuh penghormatan. 2. Himne berisi pujian kepada Tuhan, dewa, atau tanah air. 3. Sindiran sosial adalah satire, sedangkan ratapan duka adalah elegi." },
{ q: "Ode adalah puisi yang berisi...", options: ["ejekan kepada musuh", "pujian kepada pahlawan atau tokoh yang berjasa", "kesedihan mendalam", "nasihat singkat"], answer: 1, solution: "1. Ode bernada mengagungkan dan penuh kekaguman. 2. Ode berisi pujian terhadap pahlawan atau tokoh yang berjasa. 3. Ejekan adalah satire, kesedihan adalah elegi, dan nasihat adalah epigram." },
{ q: "Epigram adalah puisi yang berisi...", options: ["cerita panjang", "pujian pahlawan", "ratapan", "ajaran atau nasihat"], answer: 3, solution: "1. Epigram bersifat didaktif, yaitu bertujuan mendidik pembaca. 2. Epigram berisi ajaran, nasihat, atau tuntunan hidup. 3. Epigram bukan cerita panjang ataupun pujian kepada pahlawan." },
{ q: "Elegi adalah puisi yang mengungkapkan...", options: ["kegembiraan", "kemarahan", "kesedihan atau duka cita", "sindiran"], answer: 2, solution: "1. Elegi bernada sendu, pilu, dan penuh kepedihan. 2. Elegi mengungkapkan kesedihan atau duka cita, misalnya atas kematian seseorang. 3. Sindiran adalah satire, sedangkan kegembiraan bukan nada elegi." },
{ q: "Puisi yang berisi sindiran atau kritik tajam terhadap kelemahan masyarakat disebut...", options: ["satire", "romansa", "ode", "balada"], answer: 0, solution: "1. Puisi ini mengkritik dengan tajam kelemahan yang ada di masyarakat. 2. Puisi yang berisi sindiran disebut satire. 3. Romansa berisi cinta, ode berisi pujian, dan balada berisi kisah." },
{ q: "Romansa adalah puisi yang berisi...", options: ["kritik sosial", "luapan perasaan kasih sayang atau cinta", "nasihat hidup", "pujian kepada Tuhan"], answer: 1, solution: "1. Romansa bernada mesra dan romantis. 2. Romansa berisi luapan perasaan kasih sayang atau cinta. 3. Kritik sosial adalah satire, nasihat adalah epigram, dan pujian Tuhan adalah himne." },
{ q: "Pilihan kata yang digunakan penyair untuk menimbulkan daya bayang dan efek tertentu disebut...", options: ["rima", "bait", "larik", "diksi"], answer: 3, solution: "1. Kata adalah bahan utama penyair dalam menciptakan puisi. 2. Pilihan kata yang khas dan tepat disebut diksi. 3. Rima adalah persamaan bunyi, bait adalah kumpulan larik, dan larik adalah baris puisi." },
{ q: "Persamaan bunyi pada akhir larik-larik puisi disebut...", options: ["diksi", "tipografi", "rima", "irama"], answer: 2, solution: "1. Bunyi yang berulang pada akhir baris menciptakan kemerduan puisi. 2. Persamaan bunyi tersebut disebut rima atau persajakan. 3. Diksi adalah pilihan kata, sedangkan tipografi adalah bentuk visual puisi." },
{ q: "Sekumpulan larik yang tersusun dalam satu kesatuan pada puisi disebut...", options: ["bait", "larik", "rima", "diksi"], answer: 0, solution: "1. Puisi terbagi dalam kelompok-kelompok baris yang membentuk kesatuan. 2. Sekumpulan larik tersebut disebut bait, seperti paragraf dalam prosa. 3. Larik adalah satu baris, rima adalah persamaan bunyi." },
{ q: "Satu baris dalam puisi disebut...", options: ["bait", "larik", "stanza", "rima"], answer: 1, solution: "1. Puisi tersusun dari baris-baris yang berdiri sendiri. 2. Satu baris puisi disebut larik. 3. Bait adalah kumpulan beberapa larik." },
{ q: "Tipografi dalam puisi berkaitan dengan...", options: ["pilihan kata", "persamaan bunyi", "jumlah bait", "bentuk dan susunan visual baris-baris puisi"], answer: 3, solution: "1. Tipografi berasal dari kata yang berkaitan dengan bentuk tulisan. 2. Tipografi adalah pengaturan bentuk dan susunan visual baris-baris puisi. 3. Pilihan kata adalah diksi, sedangkan persamaan bunyi adalah rima." },
{ q: "Pola rima a-b-a-b disebut rima...", options: ["peluk", "rata", "silang", "putus"], answer: 2, solution: "1. Pada pola a-b-a-b, baris pertama berbunyi sama dengan baris ketiga dan baris kedua sama dengan baris keempat. 2. Pola yang bersilangan ini disebut rima silang. 3. Rima peluk berpola a-b-b-a." },
{ q: "Fungsi diksi yang tepat dalam puisi adalah untuk...", options: ["menimbulkan daya bayang dan memperindah makna", "memperpanjang puisi", "menambah jumlah bait", "menyamakan bunyi akhir"], answer: 0, solution: "1. Kata yang tepat membuat puisi menjadi hidup dan berkesan. 2. Diksi berfungsi menimbulkan daya bayang (imaji) dan memperindah makna puisi. 3. Menyamakan bunyi akhir adalah fungsi rima, bukan diksi." },
{ q: "\"Bulan purnama tersenyum di langit malam yang bertabur bintang.\" Citraan yang dominan pada larik tersebut adalah citraan...", options: ["auditif", "visual (penglihatan)", "taktil", "penciuman"], answer: 1, solution: "1. Larik menggambarkan hal-hal yang dapat dilihat, yaitu bulan dan bintang. 2. Citraan yang berkaitan dengan indra penglihatan disebut citraan visual. 3. Citraan auditif berkaitan dengan pendengaran, taktil dengan sentuhan." },
{ q: "\"Gemercik air sungai terdengar merdu di kejauhan.\" Citraan pada larik tersebut adalah citraan...", options: ["visual", "taktil", "gerak", "auditif (pendengaran)"], answer: 3, solution: "1. Kata gemercik dan terdengar berkaitan dengan bunyi. 2. Citraan yang berkaitan dengan indra pendengaran disebut citraan auditif. 3. Citraan visual berkaitan dengan penglihatan, bukan bunyi." },
{ q: "\"Kulitnya halus selembut sutra saat kusentuh.\" Citraan pada larik tersebut adalah citraan...", options: ["taktil (perabaan)", "visual", "auditif", "penciuman"], answer: 0, solution: "1. Kata halus dan kusentuh berkaitan dengan indra peraba. 2. Citraan yang berkaitan dengan indra perabaan disebut citraan taktil. 3. Citraan ini bukan penglihatan, pendengaran, atau penciuman." },
{ q: "\"Aroma melati merebak memenuhi taman di pagi hari.\" Citraan pada larik tersebut adalah citraan...", options: ["pengecapan", "visual", "penciuman", "taktil"], answer: 2, solution: "1. Kata aroma berkaitan dengan indra penciuman atau hidung. 2. Citraan penciuman disebut juga citraan olfaktori. 3. Citraan pengecapan berkaitan dengan rasa di lidah, bukan bau." },
{ q: "\"Daun-daun berguguran menari ditiup angin.\" Citraan gerak pada larik tersebut ditunjukkan oleh kata...", options: ["daun-daun", "berguguran menari", "ditiup", "angin"], answer: 1, solution: "1. Citraan gerak menggambarkan suatu pergerakan yang dapat dibayangkan. 2. Frasa berguguran menari menunjukkan gerakan daun yang jelas. 3. Kata lain hanya menunjukkan objek atau penyebab gerakan." },
{ q: "Citraan atau imaji dalam puisi berfungsi untuk...", options: ["menambah jumlah kata", "mempersulit pemahaman", "menghilangkan makna", "membuat pembaca seolah melihat, mendengar, dan merasakan"], answer: 3, solution: "1. Puisi ingin menghadirkan pengalaman yang konkret bagi pembaca. 2. Citraan membuat pembaca seolah melihat, mendengar, dan merasakan langsung apa yang digambarkan. 3. Citraan justru memperjelas dan memperindah makna, bukan mempersulit." },
{ q: "\"Angin malam berbisik di telingaku.\" Majas yang digunakan pada kalimat tersebut adalah...", options: ["metafora", "personifikasi", "hiperbola", "simile"], answer: 1, solution: "1. Angin adalah benda mati yang digambarkan bisa berbisik seperti manusia. 2. Pemberian sifat atau perilaku manusia pada benda mati disebut personifikasi. 3. Kalimat ini bukan perbandingan langsung seperti metafora atau simile." },
{ q: "\"Mampirlah ke gubuk kami yang kecil ini.\" (padahal rumahnya besar dan mewah). Majas yang digunakan adalah...", options: ["hiperbola", "ironi", "litotes", "sarkasme"], answer: 2, solution: "1. Pembicara merendahkan miliknya sendiri untuk menghormati lawan bicara. 2. Gaya bahasa merendahkan diri disebut litotes. 3. Kalimat ini bukan sindiran seperti ironi atau sarkasme." },
{ q: "\"Wah, rapi sekali kamarmu!\" (padahal kamarnya berantakan). Kalimat tersebut menggunakan majas...", options: ["ironi", "sarkasme", "litotes", "eufemisme"], answer: 0, solution: "1. Makna kalimat berlawanan dengan kenyataan, tetapi disampaikan secara halus. 2. Sindiran halus yang maknanya bertentangan dengan fakta disebut ironi. 3. Sarkasme lebih kasar dan pedas, sedangkan litotes merendahkan diri." },
{ q: "\"Dasar bodoh, soal semudah itu saja tidak bisa!\" Majas yang digunakan pada kalimat tersebut adalah...", options: ["ironi", "litotes", "eufemisme", "sarkasme"], answer: 3, solution: "1. Sindiran disampaikan dengan kata-kata kasar dan menyakitkan hati. 2. Sindiran yang kasar dan pedas disebut sarkasme. 3. Ironi lebih halus, litotes merendahkan diri, dan eufemisme menghaluskan kata." },
{ q: "\"Ia merasa kesepian di tengah keramaian pesta.\" Majas yang digunakan pada kalimat tersebut adalah...", options: ["antitesis", "pleonasme", "paradoks", "repetisi"], answer: 2, solution: "1. Kesepian dan keramaian adalah dua hal yang bertentangan, tetapi pernyataan itu benar adanya. 2. Pertentangan yang mengandung kebenaran disebut paradoks. 3. Antitesis hanya mempertentangkan dua kata tanpa kebenaran tersirat." },
{ q: "\"Tua muda, besar kecil, semua ikut gotong royong.\" Majas yang digunakan pada kalimat tersebut adalah...", options: ["antitesis", "paradoks", "klimaks", "repetisi"], answer: 0, solution: "1. Pasangan kata yang berlawanan, yaitu tua-muda dan besar-kecil, disejajarkan dalam satu kalimat. 2. Penggabungan dua hal yang bertentangan disebut antitesis. 3. Kalimat ini bukan paradoks karena tidak mengandung kebenaran tersirat." },
{ q: "Kata \"tuna wisma\" sebagai pengganti kata \"gelandangan\" merupakan contoh majas...", options: ["sarkasme", "eufemisme", "pleonasme", "ironi"], answer: 1, solution: "1. Kata yang kasar diganti dengan kata yang lebih halus dan sopan. 2. Penghalusan kata atau ungkapan disebut eufemisme. 3. Kalimat ini bukan sindiran ataupun penggunaan kata yang berlebihan." },
{ q: "\"Ia naik ke atas loteng untuk mengambil layang-layang.\" Kata yang menunjukkan majas pleonasme adalah...", options: ["mengambil layang-layang", "ke atas loteng", "ia naik", "naik ke atas"], answer: 3, solution: "1. Kata naik sudah berarti bergerak ke atas, sehingga tambahan ke atas tidak diperlukan. 2. Penggunaan kata yang berlebihan dan tidak perlu disebut pleonasme. 3. Bagian lain kalimat tidak mengandung kelebihan kata." },
{ q: "\"Berhenti! Berhenti! Jangan lanjutkan pertengkaran ini!\" Majas yang digunakan pada kalimat tersebut adalah...", options: ["pleonasme", "retoris", "repetisi", "klimaks"], answer: 2, solution: "1. Kata berhenti diulang untuk memberi penegasan. 2. Pengulangan kata atau frasa untuk penegasan disebut majas repetisi. 3. Kalimat ini bukan kalimat tanya sehingga bukan majas retoris." },
{ q: "\"Aku suka membaca Pramoedya Ananta Toer.\" (maksudnya karya-karyanya). Majas yang digunakan adalah...", options: ["metonimia", "sinekdoke", "alegori", "personifikasi"], answer: 0, solution: "1. Nama pengarang dipakai untuk menyebut karyanya yang berkaitan erat dengannya. 2. Penyebutan nama yang memiliki kaitan erat disebut metonimia. 3. Sinekdoke berkaitan dengan sebagian atau keseluruhan, bukan nama pengganti." },
{ q: "\"Sudah lama batang hidungnya tidak kelihatan.\" Majas sinekdoke pada kalimat tersebut termasuk jenis...", options: ["totum pro parte", "pars pro toto", "metonimia", "alegori"], answer: 1, solution: "1. Batang hidung adalah sebagian anggota tubuh yang mewakili seluruh orang. 2. Penyebutan sebagian untuk mewakili keseluruhan disebut pars pro toto. 3. Totum pro parte adalah kebalikannya, yaitu keseluruhan untuk sebagian." },
{ q: "\"Indonesia menang atas Malaysia dengan skor 2-0.\" (maksudnya tim sepak bola). Majas yang digunakan adalah sinekdoke...", options: ["pars pro toto", "metafora", "metonimia", "totum pro parte"], answer: 3, solution: "1. Indonesia sebagai keseluruhan dipakai untuk menyebut sebagian, yaitu tim sepak bolanya. 2. Penyebutan keseluruhan untuk sebagian disebut totum pro parte. 3. Pars pro toto adalah sebaliknya, yaitu sebagian untuk keseluruhan." },
{ q: "Cerita kiasan yang melukiskan suatu hal dengan simbol-simbol secara berkesinambungan disebut majas...", options: ["satire", "parabel", "alegori", "fabel"], answer: 2, solution: "1. Seluruh isi cerita menjadi kiasan atau lambang dari hal lain. 2. Kiasan yang berkesinambungan sepanjang cerita disebut alegori. 3. Fabel adalah jenis cerita tentang hewan, bukan nama majas." },
{ q: "\"Mulai dari ketua RT, ketua RW, lurah, camat, hingga bupati hadir dalam acara itu.\" Majas yang digunakan adalah...", options: ["klimaks", "antiklimaks", "repetisi", "paradoks"], answer: 0, solution: "1. Jabatan-jabatan disusun bertingkat dari yang rendah ke yang tinggi. 2. Susunan yang bertingkat naik disebut majas klimaks. 3. Antiklimaks adalah kebalikannya, yaitu susunan bertingkat turun." },
{ q: "\"Apakah pantas seorang pelajar bermalas-malasan setiap hari?\" Kalimat tersebut menggunakan majas...", options: ["litotes", "retoris", "sarkasme", "eufemisme"], answer: 1, solution: "1. Kalimat berupa pertanyaan yang tidak membutuhkan jawaban dan bertujuan menegaskan. 2. Pertanyaan yang tidak memerlukan jawaban disebut majas retoris. 3. Kalimat ini bukan sindiran kasar ataupun penghalusan kata." },
{ q: "Bentuk baku dari kata \"apotik\" adalah ....", options: ["Apotek","Apotik","Apoteq","Afotek"], answer: 0, solution: "1. Kata baku adalah kata yang sesuai dengan KBBI dan kaidah bahasa Indonesia. 2. Penulisan yang benar untuk tempat menjual obat adalah \"apotek\", bukan \"apotik\". 3. Jadi, bentuk baku dari \"apotik\" adalah \"apotek\"." },
{ q: "Penulisan kata yang baku adalah ....", options: ["Aktifitas","Aktivitas","Aktivity","Aktipitas"], answer: 1, solution: "1. Kata serapan dari \"activity\" dibakukan menjadi \"aktivitas\". 2. Bentuk \"aktifitas\" dan \"aktipitas\" tidak baku. 3. Jadi, penulisan yang baku adalah \"aktivitas\"." },
{ q: "Kalimat berikut yang menggunakan kata baku adalah ....", options: ["Saya akan menelepon dia nanti.","Saya akan telepon dia nanti.","Saya akan menelpon dia nanti.","Saya akan mentelepon dia nanti."], answer: 0, solution: "1. Kata dasar yang baku adalah \"telepon\", bukan \"telpon\". 2. Kata \"telepon\" mendapat awalan \"me-\" menjadi \"menelepon\" karena huruf t luluh. 3. Jadi, kalimat yang menggunakan kata baku adalah \"Saya akan menelepon dia nanti\"." },
{ q: "Bentuk baku dari \"resiko\" adalah ....", options: ["Resico","Riscow","Resiko","Risiko"], answer: 3, solution: "1. Kata baku diserap dari bahasa Inggris \"risk\" menjadi \"risiko\". 2. Bentuk \"resiko\" adalah penulisan yang tidak baku. 3. Jadi, bentuk baku dari \"resiko\" adalah \"risiko\"." },
{ q: "Penulisan yang tepat untuk surat permohonan adalah ....", options: ["Surat ijin mengikuti kegiatan","Surat isin mengikuti kegiatan","Surat izin mengikuti kegiatan","Surat ijinn mengikuti kegiatan"], answer: 2, solution: "1. Kata baku untuk pernyataan memperbolehkan adalah \"izin\", bukan \"ijin\". 2. Bentuk \"isin\" dan \"ijinn\" tidak ada dalam KBBI. 3. Jadi, penulisan yang tepat adalah \"Surat izin mengikuti kegiatan\"." },
{ q: "Kata baku dari \"praktek\" adalah ....", options: ["Praktek","Praktik","Pratik","Praktiq"], answer: 1, solution: "1. Kata serapan dari \"practice\" dibakukan menjadi \"praktik\". 2. Bentuk \"praktek\" adalah penulisan yang tidak baku. 3. Jadi, kata baku dari \"praktek\" adalah \"praktik\"." },
{ q: "Kalimat yang menggunakan kata baku adalah ....", options: ["Penumpang diminta antri dengan tertib.","Penumpang diminta antre dengan tertib.","Penumpang diminta ngantri dengan tertib.","Penumpang diminta berantri dengan tertib."], answer: 1, solution: "1. Kata baku untuk berbaris menunggu giliran adalah \"antre\", bukan \"antri\". 2. Bentuk \"ngantri\" adalah bahasa cakapan dan \"berantri\" tidak baku. 3. Jadi, kalimat yang menggunakan kata baku adalah \"Penumpang diminta antre dengan tertib\"." },
{ q: "Bentuk baku dari \"nasehat\" adalah ....", options: ["Nasehat","Nasihat","Nashihat","Nasheat"], answer: 1, solution: "1. Kata baku untuk petunjuk baik adalah \"nasihat\", bukan \"nasehat\". 2. Penulisan dengan huruf e pada suku kata kedua tidak sesuai KBBI. 3. Jadi, bentuk baku dari \"nasehat\" adalah \"nasihat\"." },
{ q: "Bentuk baku dari \"hutang\" adalah ....", options: ["Hutang","Huttang","Uttang","Utang"], answer: 3, solution: "1. Kata baku untuk pinjaman yang harus dibayar adalah \"utang\", bukan \"hutang\". 2. Huruf h pada awal kata tersebut tidak baku. 3. Jadi, penulisan kata yang baku adalah \"utang\"." },
{ q: "Kata berikut yang sudah baku adalah ....", options: ["Kuorum","Korum","Kuworum","Quorum"], answer: 0, solution: "1. Kata \"kuorum\" diserap dari bahasa Belanda \"quorum\" dan sudah dibakukan. 2. Bentuk \"korum\" dan \"kuworum\" tidak ada dalam KBBI. 3. Jadi, kata yang sudah baku adalah \"kuorum\"." },
{ q: "Kata \"salat\" diserap dari bahasa ....", options: ["Belanda","Arab","Portugis","Sanskerta"], answer: 1, solution: "1. Kata \"salat\" berkaitan dengan ibadah dalam agama Islam. 2. Istilah-istilah keagamaan Islam umumnya diserap dari bahasa Arab. 3. Jadi, kata \"salat\" diserap dari bahasa Arab." },
{ q: "Kata \"kantor\" diserap dari bahasa ....", options: ["Belanda","Inggris","Arab","Sanskerta"], answer: 0, solution: "1. Kata \"kantor\" berasal dari kata Belanda \"kantoor\". 2. Banyak kata berkaitan administrasi peninggalan kolonial diserap dari bahasa Belanda. 3. Jadi, kata \"kantor\" diserap dari bahasa Belanda." },
{ q: "Kata \"sepatu\" berasal dari bahasa ....", options: ["Belanda","Portugis","Spanyol","Arab"], answer: 1, solution: "1. Kata \"sepatu\" berasal dari kata Portugis \"sapato\". 2. Bangsa Portugis membawa banyak kosakata benda sehari-hari ke Nusantara. 3. Jadi, kata \"sepatu\" berasal dari bahasa Portugis." },
{ q: "Kata \"meja\" diserap dari bahasa ....", options: ["Belanda","Arab","Sanskerta","Portugis"], answer: 3, solution: "1. Kata \"meja\" berasal dari kata Portugis \"mesa\". 2. Kata ini masuk bersama kata benda rumah tangga lain seperti \"jendela\" dan \"sepatu\". 3. Jadi, kata \"meja\" diserap dari bahasa Portugis." },
{ q: "Kata \"jendela\" berasal dari bahasa Portugis, yaitu dari kata ....", options: ["Janella","Window","Ventana","Fenster"], answer: 0, solution: "1. Kata \"jendela\" diserap dari bahasa Portugis. 2. Kata asalnya adalah \"janella\" yang berarti lubang angin atau tingkap. 3. Jadi, kata \"jendela\" berasal dari kata Portugis \"janella\"." },
{ q: "Kata \"bahasa\" diserap dari bahasa Sanskerta, yaitu dari kata ....", options: ["Lingua","Bhasa","Lughat","Yuyan"], answer: 1, solution: "1. Kata \"bahasa\" berasal dari bahasa Sanskerta. 2. Kata asalnya adalah \"bhasa\" yang berarti ujaran atau perkataan. 3. Jadi, kata \"bahasa\" diserap dari kata Sanskerta \"bhasa\"." },
{ q: "Kata \"agama\" berasal dari bahasa ....", options: ["Arab","Sanskerta","Belanda","Portugis"], answer: 1, solution: "1. Kata \"agama\" sudah dikenal sejak zaman Hindu-Buddha di Nusantara. 2. Kata ini berasal dari bahasa Sanskerta \"agama\" yang berarti ajaran atau tradisi. 3. Jadi, kata \"agama\" berasal dari bahasa Sanskerta." },
{ q: "Kata \"zakat\" diserap dari bahasa ....", options: ["Belanda","Arab","Sanskerta","Portugis"], answer: 1, solution: "1. Kata \"zakat\" berkaitan dengan kewajiban dalam agama Islam. 2. Istilah keagamaan Islam umumnya diserap dari bahasa Arab. 3. Jadi, kata \"zakat\" diserap dari bahasa Arab." },
{ q: "Bentuk yang tepat dari \"me-\" + \"ajar\" adalah ....", options: ["Mengajar","Meajar","Menajar","Mengejar"], answer: 0, solution: "1. Kata dasar \"ajar\" diawali huruf vokal a. 2. Awalan \"me-\" pada kata berhuruf vokal menjadi \"meng-\". 3. Jadi, bentuk yang tepat adalah \"mengajar\"." },
{ q: "Bentuk yang tepat dari \"me-\" + \"nyanyi\" adalah ....", options: ["Menyanyi","Mennyanyi","Menyanyikan","Menanyi"], answer: 0, solution: "1. Kata dasar \"nyanyi\" diawali huruf n. 2. Awalan \"me-\" pada kata berhuruf n menjadi \"meny-\". 3. Jadi, bentuk yang tepat adalah \"menyanyi\"." },
{ q: "Bentuk yang tepat dari \"me-\" + \"pel\" adalah ....", options: ["Mengepel","Mempel","Memel","Mepel"], answer: 0, solution: "1. Kata dasar \"pel\" hanya terdiri dari satu suku kata. 2. Untuk kata dasar satu suku kata, imbuhan \"me-\" menjadi \"menge-\". 3. Jadi, bentuk yang tepat adalah \"mengepel\"." },
{ q: "Kata \"berlari\" terbentuk dari ....", options: ["ber- + lari","me- + lari","di- + lari","ter- + lari"], answer: 0, solution: "1. Kata \"berlari\" diawali dengan unsur \"ber-\". 2. Kata dasarnya adalah \"lari\" yang berarti bergerak cepat dengan kaki. 3. Jadi, kata \"berlari\" terbentuk dari \"ber-\" + \"lari\"." },
{ q: "Kalimat yang menggunakan imbuhan \"di-\" dengan tepat adalah ....", options: ["Buku itu dibaca oleh adik.","Buku itu membaca oleh adik.","Buku itu terbaca oleh adik.","Buku itu berbaca oleh adik."], answer: 0, solution: "1. Imbuhan \"di-\" membentuk kata kerja pasif. 2. Subjek \"buku\" dikenai pekerjaan membaca oleh \"adik\". 3. Jadi, kalimat yang tepat adalah \"Buku itu dibaca oleh adik\"." },
{ q: "Kata \"terlihat\" pada kalimat \"Gunung itu terlihat jelas dari sini\" menggunakan imbuhan ....", options: ["ber-","me-","di-","ter-"], answer: 3, solution: "1. Kata \"terlihat\" diawali unsur \"ter-\". 2. Kata dasarnya adalah \"lihat\" yang mendapat awalan \"ter-\". 3. Jadi, imbuhan yang digunakan adalah \"ter-\"." },
{ q: "Kata \"kedua\" pada kalimat \"Ia juara kedua lomba itu\" menggunakan imbuhan ....", options: ["di-","ke-","-an","pe-"], answer: 1, solution: "1. Kata \"kedua\" menyatakan urutan atau bilangan tingkat. 2. Bilangan tingkat dibentuk dengan awalan \"ke-\" pada kata bilangan. 3. Jadi, imbuhan yang digunakan adalah \"ke-\"." },
{ q: "Kata \"pelajar\" terbentuk dari kata dasar \"ajar\" dengan imbuhan ....", options: ["pe-","ber-","-an","-i"], answer: 0, solution: "1. Kata \"pelajar\" berarti orang yang belajar. 2. Kata dasar \"ajar\" mendapat awalan \"pe-\" yang membentuk kata benda pelaku. 3. Jadi, imbuhan yang digunakan adalah \"pe-\"." },
{ q: "Kata \"datangi\" pada kalimat \"Datangi gurumu setelah pelajaran usai\" menggunakan imbuhan ....", options: ["-kan","-i","-an","ke-"], answer: 1, solution: "1. Kata \"datangi\" berasal dari kata dasar \"datang\". 2. Kata dasar \"datang\" mendapat akhiran \"-i\" yang menunjukkan arah atau tempat tujuan. 3. Jadi, imbuhan yang digunakan adalah \"-i\"." },
{ q: "Kata \"mempermainkan\" terbentuk dari gabungan imbuhan ....", options: ["me- dan -kan","me-, per-, dan -kan","memper- dan -an","me- dan -i"], answer: 1, solution: "1. Kata \"mempermainkan\" berasal dari kata dasar \"main\". 2. Kata dasar \"main\" mendapat awalan gabungan \"memper-\" (me- + per-) dan akhiran \"-kan\". 3. Jadi, gabungan imbuhannya adalah \"me-\", \"per-\", dan \"-kan\"." },
{ q: "Kalimat berikut yang mengandung pleonasme (pemborosan kata) adalah ....", options: ["Para siswa-siswa berkumpul di lapangan.","Para siswa berkumpul di lapangan.","Siswa-siswa itu berkumpul di lapangan.","Mereka berkumpul di lapangan."], answer: 0, solution: "1. Pleonasme adalah pemakaian kata yang berlebihan karena maknanya sudah terkandung dalam kata lain. 2. Kata \"para\" sudah bermakna banyak, sehingga tidak perlu ditambah \"siswa-siswa\" yang juga bermakna banyak. 3. Jadi, kalimat yang mengandung pleonasme adalah \"Para siswa-siswa berkumpul di lapangan\"." },
{ q: "Perbaikan yang tepat untuk kalimat \"Ia belajar giat demi untuk lulus ujian\" adalah ....", options: ["Ia belajar giat demi untuk lulus ujian.","Ia belajar giat demi lulus ujian.","Ia belajar giat untuk demi lulus ujian.","Ia belajar giat supaya untuk lulus ujian."], answer: 1, solution: "1. Kata \"demi\" dan \"untuk\" memiliki makna yang sama, yaitu menyatakan tujuan. 2. Memakai keduanya sekaligus merupakan pemborosan kata. 3. Jadi, perbaikan yang tepat adalah \"Ia belajar giat demi lulus ujian\"." },
{ q: "Kalimat yang hemat kata adalah ....", options: ["Para siswa naik ke atas panggung.","Para siswa-siswa naik ke atas panggung.","Para siswa naik ke panggung.","Para siswa naik ke atas panggung pentas."], answer: 2, solution: "1. Kalimat efektif harus hemat, tidak memakai kata yang berlebihan. 2. Kata \"naik\" sudah mengandung makna \"ke atas\" dan \"panggung\" sudah berarti tempat pentas. 3. Jadi, kalimat yang hemat kata adalah \"Para siswa naik ke panggung\"." },
{ q: "Kalimat berikut yang memiliki kesejajaran (paralelisme) bentuk kata adalah ....", options: ["Hobinya adalah membaca, menulis, dan melukis.","Hobinya adalah membaca, menulis, dan lukisan.","Hobinya adalah membaca, menulis, dan ia melukis.","Hobinya membaca buku, menulis karangan, dan lukisan."], answer: 0, solution: "1. Kesejajaran berarti unsur-unsur yang sederajat harus memakai bentuk kata yang sama. 2. Pada kalimat yang benar, ketiga unsur memakai bentuk yang sama, yaitu \"membaca, menulis, dan melukis\". 3. Pilihan lain mencampur kata kerja dengan kata benda atau klausa." },
{ q: "Kalimat berikut yang memiliki subjek dan predikat yang jelas adalah ....", options: ["Siswa yang terlambat akan diberi sanksi.","Bagi siswa yang terlambat akan diberi sanksi.","Untuk para guru dimohon hadir tepat waktu.","Dalam acara itu dibahas kurikulum baru."], answer: 0, solution: "1. Kalimat efektif harus memiliki subjek dan predikat yang jelas. 2. Pada kalimat yang benar, subjeknya adalah \"Siswa yang terlambat\" dan predikatnya \"akan diberi sanksi\". 3. Pilihan lain diawali kata depan sehingga subjeknya tidak jelas." },
{ q: "Kalimat yang tidak efektif karena pemborosan kata adalah ....", options: ["Pemandangan di desa itu sangat indah.","Pemandangan di desa itu sangat indah sekali.","Pemandangan di desa itu indah sekali.","Desa itu memiliki pemandangan yang indah."], answer: 1, solution: "1. Kata \"sangat\" dan \"sekali\" sama-sama bermakna penguat. 2. Memakai keduanya sekaligus adalah pemborosan kata. 3. Jadi, kalimat yang tidak efektif adalah \"Pemandangan di desa itu sangat indah sekali\"." },
{ q: "Perbaikan yang tepat untuk kalimat \"Ia berlatih setiap hari agar supaya menang\" adalah ....", options: ["Ia berlatih setiap hari agar supaya menang.","Ia berlatih setiap hari agar menang.","Ia berlatih setiap hari supaya agar menang.","Ia berlatih setiap hari demi untuk menang."], answer: 1, solution: "1. Kata \"agar\" dan \"supaya\" memiliki makna yang sama, yaitu menyatakan tujuan. 2. Memakai keduanya sekaligus merupakan pemborosan kata. 3. Jadi, perbaikan yang tepat adalah \"Ia berlatih setiap hari agar menang\"." },
{ q: "Kalimat yang efektif adalah ....", options: ["Novel ini adalah merupakan karya terbaiknya.","Novel ini adalah karya merupakan terbaiknya.","Novel ini karya adalah merupakan terbaiknya.","Novel ini merupakan karya terbaiknya."], answer: 3, solution: "1. Kata \"adalah\" dan \"merupakan\" memiliki fungsi yang sama sebagai penghubung. 2. Keduanya tidak boleh dipakai bersamaan dalam satu kalimat. 3. Jadi, kalimat yang efektif adalah \"Novel ini merupakan karya terbaiknya\"." },
{ q: "Kalimat \"Ayah membaca koran dan ibu memasak di dapur\" termasuk kalimat ....", options: ["Tunggal","Majemuk setara","Majemuk bertingkat","Majemuk campuran"], answer: 1, solution: "1. Kalimat ini memiliki dua klausa, yaitu \"Ayah membaca koran\" dan \"ibu memasak di dapur\". 2. Kedua klausa dihubungkan konjungsi \"dan\" yang sederajat kedudukannya. 3. Jadi, kalimat ini termasuk kalimat majemuk setara." },
{ q: "Kalimat \"Kami berteduh karena hujan turun dengan deras\" termasuk kalimat ....", options: ["Tunggal","Majemuk setara","Majemuk bertingkat","Majemuk campuran"], answer: 2, solution: "1. Kalimat ini memiliki induk kalimat \"Kami berteduh\" dan anak kalimat \"hujan turun dengan deras\". 2. Keduanya dihubungkan konjungsi \"karena\" yang menunjukkan hubungan bertingkat. 3. Jadi, kalimat ini termasuk kalimat majemuk bertingkat." },
{ q: "Kalimat \"Buku yang di atas meja itu milik kakak\" termasuk kalimat ....", options: ["Tunggal","Majemuk bertingkat","Majemuk setara","Majemuk setara bertingkat"], answer: 1, solution: "1. Klausa \"yang di atas meja\" menjelaskan kata \"buku\" dan tidak dapat berdiri sendiri. 2. Klausa penjelas yang diawali \"yang\" merupakan anak kalimat. 3. Jadi, kalimat ini termasuk kalimat majemuk bertingkat." },
{ q: "Konjungsi yang tepat untuk melengkapi kalimat majemuk setara \"Dia rajin belajar ... adiknya malas\" adalah ....", options: ["karena","sehingga","yang","tetapi"], answer: 3, solution: "1. Kedua klausa dalam kalimat ini sederajat dan bertentangan maknanya. 2. Konjungsi setara yang menyatakan pertentangan adalah \"tetapi\". 3. Jadi, konjungsi yang tepat adalah \"tetapi\"." },
{ q: "Kalimat \"Ia berlatih keras sehingga menjadi juara kelas\" termasuk kalimat ....", options: ["Tunggal","Majemuk setara","Majemuk bertingkat","Majemuk rapatan"], answer: 2, solution: "1. Konjungsi \"sehingga\" menghubungkan induk kalimat \"Ia berlatih keras\" dengan anak kalimat \"menjadi juara kelas\". 2. Hubungan antarklausa ini tidak sederajat, melainkan bertingkat karena menyatakan akibat. 3. Jadi, kalimat ini termasuk kalimat majemuk bertingkat." },
{ q: "Kalimat berikut yang termasuk kalimat tunggal adalah ....", options: ["Kucing itu tidur di atas sofa.","Kucing itu tidur dan anjing menggonggong.","Kucing itu tidur karena kelelahan.","Kucing yang gemuk itu tidur di sofa."], answer: 0, solution: "1. Kalimat tunggal hanya memiliki satu subjek dan satu predikat. 2. Kalimat \"Kucing itu tidur di atas sofa\" hanya memiliki subjek \"Kucing itu\" dan predikat \"tidur\". 3. Pilihan lain memiliki dua klausa, sedangkan pilihan terakhir memiliki anak kalimat \"yang gemuk\"." },
{ q: "Konjungsi antarkalimat yang tepat untuk melengkapi \"Hujan turun sangat deras. ..., pertandingan tetap dilanjutkan\" adalah ....", options: ["namun","tetapi","karena","dan"], answer: 0, solution: "1. Konjungsi antarkalimat dipakai di awal kalimat untuk menghubungkan dengan kalimat sebelumnya. 2. Kata \"namun\" dipakai setelah tanda titik dan diikuti koma. 3. Jadi, konjungsi yang tepat adalah \"namun\"." },
{ q: "Kalimat \"Acara dimulai tepat waktu. Oleh karena itu, semua peserta diminta hadir lebih awal\" menggunakan konjungsi ....", options: ["intrakalimat","antarkalimat","korelatif","subordinatif"], answer: 1, solution: "1. Konjungsi \"oleh karena itu\" terletak di awal kalimat kedua. 2. Konjungsi yang menghubungkan dua kalimat yang terpisah tanda titik disebut konjungsi antarkalimat. 3. Jadi, kalimat tersebut menggunakan konjungsi antarkalimat." },
{ q: "Konjungsi antarkalimat yang menyatakan pertentangan adalah ....", options: ["akan tetapi","dan","karena","sehingga"], answer: 0, solution: "1. Konjungsi antarkalimat dipakai di awal kalimat setelah tanda titik. 2. Frasa \"akan tetapi\" menyatakan pertentangan dengan kalimat sebelumnya. 3. Jadi, konjungsi antarkalimat yang menyatakan pertentangan adalah \"akan tetapi\"." },
{ q: "Konjungsi intrakalimat pada kalimat \"Dia ingin ikut, tetapi kakinya sedang sakit\" adalah ....", options: ["Dia","tetapi","ingin","sedang"], answer: 1, solution: "1. Konjungsi intrakalimat menghubungkan dua klausa di dalam satu kalimat. 2. Kata \"tetapi\" menghubungkan klausa \"Dia ingin ikut\" dengan klausa \"kakinya sedang sakit\". 3. Jadi, konjungsi intrakalimatnya adalah \"tetapi\"." },
{ q: "Konjungsi yang tepat untuk melengkapi \"Buku ini sangat bermanfaat. ..., harganya cukup terjangkau\" adalah ....", options: ["karena","selain itu","sehingga","yang"], answer: 1, solution: "1. Kalimat kedua menambahkan informasi dari kalimat pertama. 2. Konjungsi antarkalimat yang menyatakan penambahan informasi adalah \"selain itu\". 3. Jadi, konjungsi yang tepat adalah \"selain itu\"." },
{ q: "Perbedaan konjungsi \"tetapi\" dan \"akan tetapi\" adalah ....", options: ["\"tetapi\" antarkalimat, \"akan tetapi\" intrakalimat","\"tetapi\" intrakalimat, \"akan tetapi\" antarkalimat","Keduanya konjungsi intrakalimat","Keduanya konjungsi antarkalimat"], answer: 1, solution: "1. Kata \"tetapi\" dipakai di dalam satu kalimat untuk menghubungkan dua klausa. 2. Frasa \"akan tetapi\" dipakai di awal kalimat baru setelah tanda titik. 3. Jadi, \"tetapi\" adalah konjungsi intrakalimat sedangkan \"akan tetapi\" adalah konjungsi antarkalimat." },
{ q: "Tanda baca yang tepat untuk mengakhiri kalimat \"Ibu pergi ke pasar\" adalah ....", options: ["Koma (,)","Titik dua (:)","Tanda seru (!)", "Titik (.)"], answer: 3, solution: "1. Kalimat \"Ibu pergi ke pasar\" adalah kalimat berita. 2. Kalimat berita diakhiri dengan tanda titik. 3. Jadi, tanda baca yang tepat adalah titik (.)." },
{ q: "Penggunaan tanda koma yang tepat adalah ....", options: ["Karena hujan, kami berteduh di pos ronda.","Karena hujan kami berteduh di pos ronda.","Karena, hujan kami berteduh di pos ronda.","Karena hujan kami, berteduh di pos ronda."], answer: 0, solution: "1. Tanda koma dipakai untuk memisahkan anak kalimat yang mendahului induk kalimat. 2. Pada kalimat ini, anak kalimat \"Karena hujan\" mendahului induk kalimat \"kami berteduh di pos ronda\". 3. Jadi, koma diletakkan setelah anak kalimat." },
{ q: "Tanda baca yang tepat untuk kalimat \"Barang yang dibutuhkan adalah beras gula dan minyak\" adalah ....", options: ["Koma setelah kata \"adalah\"","Titik dua setelah kata \"adalah\"","Titik setelah kata \"adalah\"","Tanda petik setelah kata \"adalah\""], answer: 1, solution: "1. Tanda titik dua dipakai sebelum rincian atau penjelasan. 2. Kata \"beras, gula, dan minyak\" merupakan rincian dari barang yang dibutuhkan. 3. Jadi, kalimat yang tepat memakai titik dua setelah kata \"adalah\"." },
{ q: "Penulisan judul buku dalam kalimat yang tepat adalah ....", options: ["Saya membaca novel Laskar Pelangi kemarin.", "Saya membaca novel \"Laskar Pelangi\" kemarin.", "Saya membaca novel 'Laskar Pelangi' kemarin.", "Saya membaca novel (Laskar Pelangi) kemarin."], answer: 1, solution: "1. Tanda petik ganda dipakai untuk mengapit judul buku, karangan, atau bab. 2. Judul novel \"Laskar Pelangi\" harus diapit tanda petik ganda. 3. Jadi, penulisan yang tepat memakai tanda petik ganda pada judul tersebut." },
{ q: "Tanda baca yang tepat untuk kalimat perintah \"Pergilah sekarang\" adalah ....", options: ["Titik (.)","Koma (, )","Tanda seru (!)", "Tanda tanya (?)"], answer: 2, solution: "1. Kalimat perintah yang diucapkan dengan nada tegas diakhiri tanda seru. 2. Kalimat \"Pergilah sekarang\" adalah perintah yang tegas. 3. Jadi, tanda baca yang tepat adalah tanda seru (!)." },
{ q: "Kalimat tanya yang tepat adalah ....", options: ["Kapan kamu datang.","Kapan kamu datang?","Kapan kamu datang!","Kapan kamu datang,"], answer: 1, solution: "1. Kalimat tanya adalah kalimat yang menanyakan sesuatu. 2. Kalimat tanya selalu diakhiri dengan tanda tanya. 3. Jadi, kalimat tanya yang tepat adalah \"Kapan kamu datang?\"." },
{ q: "Penulisan dengan tanda hubung yang tepat adalah ....", options: ["Tahun 1990an","Tahun-1990an","1990-an tahun","Tahun 1990-an"], answer: 3, solution: "1. Tanda hubung dipakai untuk merangkai angka dengan akhiran \"-an\". 2. Bentuk yang benar adalah \"1990-an\" yang dibaca \"seribu sembilan ratus sembilan puluhan\". 3. Jadi, penulisan yang tepat adalah \"Tahun 1990-an\"." },
{ q: "Tanda elipsis (...) dipakai untuk menunjukkan ....", options: ["Kalimat yang terputus-putus atau bagian yang dihilangkan","Akhir kalimat berita","Rincian sebuah penjelasan","Judul sebuah karangan"], answer: 0, solution: "1. Tanda elipsis berupa tiga titik yang menunjukkan kalimat terputus atau bagian naskah yang dihilangkan. 2. Contohnya: \"Kalau begitu ... terserah kamu saja.\" 3. Jadi, elipsis dipakai untuk menunjukkan kalimat yang terputus-putus atau bagian yang dihilangkan." },
{ q: "Penulisan huruf kapital yang tepat adalah ....", options: ["Saya pergi ke Jakarta kemarin.","saya pergi ke jakarta kemarin.","Saya pergi ke jakarta kemarin.","saya pergi ke Jakarta kemarin."], answer: 0, solution: "1. Huruf kapital dipakai pada awal kalimat dan nama geografi. 2. Kata \"Saya\" di awal kalimat dan \"Jakarta\" sebagai nama kota harus kapital. 3. Jadi, penulisan yang tepat adalah \"Saya pergi ke Jakarta kemarin\"." },
{ q: "Penulisan nama orang yang tepat adalah ....", options: ["budi santoso","Budi santoso","Budi Santoso","BUDI SANTOSO"], answer: 2, solution: "1. Nama orang ditulis dengan huruf kapital pada setiap unsurnya. 2. Nama \"Budi Santoso\" terdiri dari dua unsur yang keduanya kapital. 3. Jadi, penulisan yang tepat adalah \"Budi Santoso\"." },
{ q: "Penulisan nama hari yang tepat adalah ....", options: ["senin","SENIN","Senin","sEnin"], answer: 2, solution: "1. Nama hari, bulan, dan hari raya ditulis dengan huruf kapital. 2. Kata \"senin\" adalah nama hari sehingga huruf awalnya kapital. 3. Jadi, penulisan yang tepat adalah \"Senin\"." },
{ q: "Penulisan nama geografi yang tepat adalah ....", options: ["sungai musi","Sungai musi","Sungai Musi","sungai Musi"], answer: 2, solution: "1. Nama geografi seperti sungai, gunung, dan danau ditulis kapital pada setiap unsurnya. 2. Kata \"Sungai\" adalah jenis geografi dan \"Musi\" adalah nama khasnya. 3. Jadi, penulisan yang tepat adalah \"Sungai Musi\"." },
{ q: "Penulisan kata sapaan kekerabatan yang tepat adalah ....", options: ["Kapan bapak datang ke sekolah?","Kapan BAPAK datang ke sekolah?","Kapan bApak datang ke sekolah?","Kapan Bapak datang ke sekolah?"], answer: 3, solution: "1. Kata sapaan kekerabatan seperti \"Bapak\" dan \"Ibu\" ditulis kapital jika dipakai sebagai sapaan. 2. Pada kalimat ini, \"Bapak\" dipakai untuk menyapa lawan bicara. 3. Jadi, penulisan yang tepat adalah \"Kapan Bapak datang ke sekolah?\"." },
{ q: "Penulisan bilangan yang tepat dalam kalimat adalah ....", options: ["Ada dua belas siswa yang mengikuti lomba.","Ada 12 siswa yang mengikuti lomba.","Ada Dua Belas siswa yang mengikuti lomba.","Ada 12 Siswa yang mengikuti lomba."], answer: 0, solution: "1. Bilangan yang dapat dinyatakan dengan satu atau dua kata ditulis dengan huruf. 2. Bilangan \"12\" dapat dinyatakan dengan dua kata, yaitu \"dua belas\". 3. Jadi, penulisan yang tepat adalah \"Ada dua belas siswa yang mengikuti lomba\"." },
{ q: "Kalimat yang diawali bilangan ditulis dengan tepat adalah ....", options: ["12 siswa mengikuti lomba cerdas cermat.","Dua Belas siswa mengikuti lomba cerdas cermat.","Dua belas siswa mengikuti lomba cerdas cermat.","12 Siswa mengikuti lomba cerdas cermat."], answer: 2, solution: "1. Bilangan pada awal kalimat tidak boleh ditulis dengan angka. 2. Bilangan tersebut harus ditulis dengan huruf. 3. Jadi, kalimat yang tepat adalah \"Dua belas siswa mengikuti lomba cerdas cermat\"." },
{ q: "Penulisan bilangan tingkat yang tepat adalah ....", options: ["Abad 21","Abad ke-21","Abad ke 21","Abad ke21"], answer: 1, solution: "1. Bilangan tingkat ditulis dengan angka yang didahului kata \"ke-\". 2. Kata \"ke\" dan angka dihubungkan dengan tanda hubung tanpa spasi. 3. Jadi, penulisan yang tepat adalah \"Abad ke-21\"." },
{ q: "Penulisan nilai mata uang yang tepat adalah ....", options: ["Rp 5.000,00","Rp. 5.000,00","Rp 5000","Rp5.000,00"], answer: 3, solution: "1. Penulisan mata uang rupiah diawali \"Rp\" tanpa spasi dan tanpa titik. 2. Ribuan dipisahkan dengan titik dan desimal dengan koma. 3. Jadi, penulisan yang tepat adalah \"Rp5.000,00\"." },
{ q: "Pidato yang bertujuan memberi informasi atau pengetahuan kepada pendengar disebut pidato ....", options: ["informatif","persuasif","rekreatif","argumentatif"], answer: 0, solution: "1. Pidato informatif bertujuan menyampaikan informasi atau pengetahuan. 2. Pendengar diharapkan bertambah wawasannya setelah mendengarkan. 3. Jadi, pidato tersebut disebut pidato informatif." },
{ q: "Pidato yang bertujuan memengaruhi atau mengajak pendengar melakukan sesuatu disebut pidato ....", options: ["informatif","rekreatif","persuasif","naratif"], answer: 2, solution: "1. Pidato persuasif bertujuan memengaruhi pendengar agar melakukan sesuatu. 2. Isinya berupa ajakan atau bujukan yang meyakinkan. 3. Jadi, pidato tersebut disebut pidato persuasif." },
{ q: "Metode berpidato secara spontan tanpa persiapan naskah disebut metode ....", options: ["naskah","impromptu","ekstemporan","memoriter"], answer: 1, solution: "1. Metode impromptu adalah berpidato secara spontan tanpa persiapan. 2. Metode naskah memakai teks lengkap, sedangkan ekstemporan memakai catatan garis besar. 3. Jadi, berpidato spontan tanpa persiapan disebut metode impromptu." },
{ q: "Metode berpidato dengan hanya berpedoman pada catatan garis besar disebut metode ....", options: ["naskah","impromptu","ekstemporan","deklamasi"], answer: 2, solution: "1. Metode ekstemporan memakai catatan kecil berisi garis besar pokok pembicaraan. 2. Pembicara mengembangkannya dengan kata-kata sendiri saat berpidato. 3. Jadi, metode tersebut disebut ekstemporan." },
{ q: "Bagian penutup pidato yang tepat adalah ....", options: ["Menyampaikan salam pembuka dan perkenalan diri","Menyampaikan kesimpulan dan ucapan terima kasih","Membacakan seluruh isi naskah pidato","Menyampaikan data dan fakta pendukung"], answer: 1, solution: "1. Bagian penutup berisi rangkuman atau kesimpulan isi pidato. 2. Penutup juga berisi ucapan terima kasih dan salam penutup. 3. Jadi, bagian penutup yang tepat adalah menyampaikan kesimpulan dan ucapan terima kasih." },
{ q: "Bagian surat yang hanya terdapat pada surat dinas adalah ....", options: ["Kop surat","Salam pembuka","Tanggal surat","Tanda tangan"], answer: 0, solution: "1. Kop surat berisi nama dan alamat instansi pengirim surat. 2. Surat pribadi tidak memakai kop surat karena bersifat perorangan. 3. Jadi, bagian yang hanya ada pada surat dinas adalah kop surat." },
{ q: "Bagian surat dinas yang menunjukkan identitas resmi surat adalah ....", options: ["Salam penutup","Isi surat","Nomor surat","Nama terang"], answer: 2, solution: "1. Nomor surat adalah kode resmi yang menunjukkan urutan dan jenis surat dinas. 2. Surat pribadi tidak memerlukan nomor surat. 3. Jadi, bagian yang menunjukkan identitas resmi surat dinas adalah nomor surat." },
{ q: "Istilah untuk salinan surat dinas yang dikirim kepada pihak lain sebagai pemberitahuan adalah ....", options: ["Lampiran","Perihal","Tembusan","Kop"], answer: 2, solution: "1. Tembusan adalah salinan surat dinas yang disampaikan kepada pihak lain yang terkait. 2. Tembusan ditulis di bagian bawah surat dinas setelah tanda tangan. 3. Jadi, istilahnya adalah tembusan." },
{ q: "Bagian surat dinas yang berisi pokok pembicaraan surat secara singkat adalah ....", options: ["Lampiran","Tembusan","Perihal","Alamat"], answer: 2, solution: "1. Perihal ditulis setelah nomor surat dan berisi pokok pembicaraan. 2. Perihal ditulis secara singkat agar penerima cepat memahami isi surat. 3. Jadi, bagian tersebut adalah perihal." },
{ q: "Bahasa yang digunakan dalam surat dinas adalah bahasa yang ....", options: ["santai dan akrab","berlebihan dan puitis","baku, lugas, dan resmi","campuran bahasa daerah"], answer: 2, solution: "1. Surat dinas bersifat resmi sehingga bahasanya harus baku. 2. Bahasa surat dinas juga harus lugas agar maksudnya jelas dan tidak bertele-tele. 3. Jadi, bahasa surat dinas adalah bahasa yang baku, lugas, dan resmi." },
{ q: "Tujuan utama teks persuasi adalah ....", options: ["Mengajak atau membujuk pembaca","Memberi informasi faktual","Menceritakan pengalaman","Mendeskripsikan objek"], answer: 0, solution: "1. Teks persuasi berisi ajakan atau bujukan kepada pembaca. 2. Pembaca diharapkan terpengaruh untuk melakukan sesuatu setelah membaca. 3. Jadi, tujuan utama teks persuasi adalah mengajak atau membujuk pembaca." },
{ q: "Struktur teks persuasi yang tepat adalah ....", options: ["Pengenalan isu, rangkaian argumen, pernyataan ajakan","Orientasi, komplikasi, resolusi","Identifikasi, klasifikasi, deskripsi","Tesis, argumen, penegasan ulang"], answer: 0, solution: "1. Teks persuasi diawali pengenalan isu atau masalah. 2. Kemudian disajikan rangkaian argumen untuk meyakinkan pembaca. 3. Bagian akhir berisi pernyataan ajakan." },
{ q: "Kalimat berikut yang merupakan kalimat ajakan dalam teks persuasi adalah ....", options: ["Sampah plastik mencemari laut.","Lingkungan yang bersih itu menyehatkan.","Marilah kita menjaga kebersihan lingkungan!","Banyak warga membuang sampah sembarangan."], answer: 2, solution: "1. Kalimat ajakan ditandai kata seperti \"marilah\" atau \"ayo\". 2. Kalimat \"Marilah kita menjaga kebersihan lingkungan!\" mengajak pembaca berbuat sesuatu. 3. Pilihan lain hanya berupa kalimat berita tanpa ajakan." },
{ q: "Ciri kebahasaan teks persuasi adalah banyak menggunakan ....", options: ["Kalimat berita yang datar","Kata ajakan seperti ayo, marilah, dan hendaknya","Istilah teknis yang sulit","Kalimat tanya tanpa jawaban"], answer: 1, solution: "1. Teks persuasi bertujuan mengajak pembaca melakukan sesuatu. 2. Untuk itu, teks persuasi memakai kata-kata ajakan seperti \"ayo\", \"marilah\", dan \"hendaknya\". 3. Jadi, ciri kebahasaannya adalah banyak menggunakan kata ajakan." },
{ q: "Pernyataan \"Kelemahan novel ini terletak pada alurnya yang berjalan lambat\" merupakan bagian resensi yang berisi ....", options: ["Kelebihan buku","Identitas buku","Sinopsis buku","Kekurangan buku"], answer: 3, solution: "1. Resensi memuat penilaian terhadap kelebihan dan kekurangan buku. 2. Pernyataan tersebut menilai sisi lemah novel, yaitu alurnya yang lambat. 3. Jadi, pernyataan itu merupakan bagian resensi yang berisi kekurangan buku." },
{ q: "Teks tanggapan berisi ....", options: ["Cerita khayalan penulis","Data hasil pengamatan","Penilaian atau evaluasi terhadap suatu karya","Langkah-langkah melakukan sesuatu"], answer: 2, solution: "1. Teks tanggapan adalah teks yang berisi respons terhadap suatu karya atau peristiwa. 2. Respons tersebut berupa penilaian, kritik, atau evaluasi yang disertai alasan. 3. Jadi, teks tanggapan berisi penilaian atau evaluasi terhadap suatu karya." },
{ q: "Bagian resensi yang memuat judul, pengarang, penerbit, dan tahun terbit disebut ....", options: ["Sinopsis","Kelemahan buku","Identitas buku","Penutup resensi"], answer: 2, solution: "1. Setiap resensi diawali dengan data-data pokok buku yang diresensi. 2. Data tersebut meliputi judul, pengarang, penerbit, dan tahun terbit. 3. Jadi, bagian tersebut disebut identitas buku." },
{ q: "Makna kata yang sesuai dengan makna kamus tanpa tambahan nilai rasa disebut makna ....", options: ["denotasi","konotasi","kias","majas"], answer: 0, solution: "1. Makna denotasi adalah makna kata yang sebenarnya sesuai kamus. 2. Makna ini bersifat lugas tanpa tambahan nilai rasa. 3. Jadi, makna tersebut disebut makna denotasi." },
{ q: "Makna kata yang mengandung nilai rasa tambahan selain makna sebenarnya disebut makna ....", options: ["denotasi","lugas","konotasi","leksikal"], answer: 2, solution: "1. Makna konotasi adalah makna tambahan di luar makna sebenarnya. 2. Makna tambahan ini mengandung nilai rasa tertentu. 3. Jadi, makna tersebut disebut makna konotasi." },
{ q: "Kata \"tinggi\" pada kalimat \"Gedung itu sangat tinggi\" bermakna ....", options: ["denotasi","konotasi","kiasan","idiom"], answer: 0, solution: "1. Makna denotasi adalah makna kata yang sebenarnya sesuai kamus. 2. Pada kalimat tersebut, \"tinggi\" berarti ukuran vertikal yang besar, sesuai makna kamusnya. 3. Jadi, kata \"tinggi\" pada kalimat itu bermakna denotasi." },
{ q: "Kata \"tikus\" pada kalimat \"Dia dijuluki tikus kantor karena sering mencuri\" bermakna ....", options: ["denotasi","lugas","konotasi","harfiah"], answer: 2, solution: "1. Makna konotasi adalah makna tambahan yang bernilai rasa. 2. Kata \"tikus\" pada kalimat itu tidak berarti hewan pengerat, melainkan orang yang suka mencuri. 3. Jadi, kata \"tikus\" pada kalimat itu bermakna konotasi." },
{ q: "Sinonim kata \"dermawan\" adalah ....", options: ["Kikir","Pelit","Pemurah","Bakhil"], answer: 2, solution: "1. Sinonim adalah persamaan kata. 2. Kata \"dermawan\" berarti suka memberi, sama maknanya dengan \"pemurah\". 3. Jadi, sinonim kata \"dermawan\" adalah \"pemurah\"." },
{ q: "Antonim kata \"kikir\" adalah ....", options: ["Pelit","Dermawan","Bakhil","Hemat"], answer: 1, solution: "1. Antonim adalah lawan kata. 2. Kata \"kikir\" berarti enggan memberi, lawannya adalah \"dermawan\" yang berarti suka memberi. 3. Jadi, antonim kata \"kikir\" adalah \"dermawan\"." },
{ q: "Antonim kata \"abadi\" adalah ....", options: ["Kekal","Lestari","Eternal","Fana"], answer: 3, solution: "1. Antonim adalah lawan kata. 2. Kata \"abadi\" berarti kekal selamanya, lawannya adalah \"fana\" yang berarti tidak kekal. 3. Jadi, antonim kata \"abadi\" adalah \"fana\"." },
{ q: "Ungkapan \"besar kepala\" berarti ....", options: ["Sakit kepala","Cerdas","Sombong","Pemimpin"], answer: 2, solution: "1. Ungkapan adalah gabungan kata yang maknanya tidak dapat ditebak dari kata pembentuknya. 2. Ungkapan \"besar kepala\" berarti sombong atau angkuh karena merasa hebat. 3. Jadi, ungkapan \"besar kepala\" berarti sombong." },
{ q: "Ungkapan \"kambing hitam\" berarti ....", options: ["Kambing berwarna hitam","Orang yang dipersalahkan","Hewan kurban","Orang yang beruntung"], answer: 1, solution: "1. Ungkapan \"kambing hitam\" tidak berarti hewan kambing yang berwarna hitam. 2. Ungkapan ini berarti orang yang dipersalahkan atas suatu kesalahan. 3. Jadi, ungkapan \"kambing hitam\" berarti orang yang dipersalahkan." },
{ q: "Arti peribahasa \"Air beriak tanda tak dalam\" adalah ....", options: ["Orang yang banyak bicara biasanya kurang berilmu","Air yang tenang sangat dalam","Orang pendiam pasti pandai","Sungai yang beriak berbahaya"], answer: 0, solution: "1. Peribahasa ini membandingkan air yang beriak dengan orang yang banyak bicara. 2. Air yang beriak biasanya tidak dalam, demikian pula orang yang banyak bicara biasanya kurang berilmu. 3. Jadi, artinya adalah orang yang banyak bicara biasanya kurang berilmu." },
{ q: "Arti peribahasa \"Bagai katak dalam tempurung\" adalah ....", options: ["Orang yang suka berenang","Orang yang pandai melompat","Orang yang wawasannya sempit","Orang yang tinggal di desa"], answer: 2, solution: "1. Katak dalam tempurung hanya melihat sebatas tempurung yang menutupinya. 2. Peribahasa ini menggambarkan orang yang wawasan dan pengetahuannya sempit. 3. Jadi, artinya adalah orang yang wawasannya sempit." },
{ q: "Arti peribahasa \"Sekali merengkuh dayung, dua tiga pulau terlampaui\" adalah ....", options: ["Mendayung dengan cepat","Berlayar ke banyak pulau","Sekali bekerja, banyak hasil yang diperoleh","Bekerja tanpa tujuan"], answer: 2, solution: "1. Peribahasa ini menggambarkan satu kali kayuhan dayung yang melampaui dua tiga pulau. 2. Maknanya adalah satu pekerjaan yang menghasilkan banyak keuntungan sekaligus. 3. Jadi, artinya adalah sekali bekerja, banyak hasil yang diperoleh." },
{ q: "Arti peribahasa \"Tong kosong nyaring bunyinya\" adalah ....", options: ["Tong yang kosong ringan diangkat","Bunyi tong yang merdu","Orang yang bodoh biasanya banyak bicara","Orang pandai selalu diam"], answer: 2, solution: "1. Tong yang kosong akan berbunyi nyaring jika dipukul, sedangkan tong berisi berbunyi pelan. 2. Peribahasa ini menggambarkan orang yang kurang berilmu tetapi banyak bicara. 3. Jadi, artinya adalah orang yang bodoh biasanya banyak bicara." }
  ]
};
